const RED_IVY = {"episodes": {"red_ivy_s1_ep01": {"story_id": "red_ivy_s1", "episode_id": "red_ivy_s1_ep01", "number": 1, "title": "A Perfect Party", "access": "free", "start": "ep01_s1_01", "scenes": [{"index": 1, "place_ko": "환영 파티 / 저녁", "background": "bg_crimson_hall_evening"}, {"index": 2, "place_ko": "VIP 라운지", "background": "bg_vip_lounge_night"}, {"index": 3, "place_ko": "라운지 바깥 복도", "background": "bg_lounge_corridor_night", "audience_background": "bg_terrace_night"}, {"index": 4, "place_ko": "다음 날 / 휴대폰", "background": "bg_campus_morning"}], "nodes": [{"kind": "line", "speaker": "narration", "channel": "narration", "text": "St. Jude University. The Crimson Club’s first party of the semester. You’re a new member helping at the welcome desk. Everyone here knows someone. Nobody seems to trust them.", "scene": 1, "directions": ["배경: 크림슨 홀. 표정: 클로이=여유 있는 미소, 올리버=지친 미소, 소피=관찰, 줄리언=장난."], "id": "ep01_s1_01", "next": "ep01_s1_02", "background": "bg_crimson_hall_evening", "ko": "세인트 주드 대학교. 크림슨 클럽의 이번 학기 첫 파티. 당신은 환영 데스크를 돕는 신입 멤버다. 이곳의 모두가 누군가를 알고 있다. 그런데 아무도 그 사람을 믿는 것 같지 않다."}, {"kind": "line", "speaker": "chloe", "channel": "speech", "text": "To old friends, new faces, and a year worth remembering.", "scene": 1, "id": "ep01_s1_02", "next": "ep01_s1_03", "background": "bg_crimson_hall_evening", "ko": "오랜 친구들과 새로운 얼굴들, 그리고 기억할 만한 한 해를 위하여.", "portrait": "chloe_standing_host"}, {"kind": "line", "speaker": "ethan", "channel": "speech", "text": "Ambitious. Most people here are trying to forget the last one.", "scene": 1, "id": "ep01_s1_03", "next": "ep01_s1_04", "background": "bg_crimson_hall_evening", "ko": "야심 차네. 여기 있는 사람들 대부분은 지난 한 해를 잊으려고 애쓰는 중인데.", "portrait": "ethan_standing_dry_amusement"}, {"kind": "line", "speaker": "julian", "channel": "speech", "text": "And that’s why Ethan doesn’t get a microphone.", "scene": 1, "id": "ep01_s1_04", "next": "ep01_s1_05", "background": "bg_crimson_hall_evening", "ko": "그래서 이든한테는 마이크를 안 주는 거야.", "portrait": "julian_standing_joke"}, {"kind": "line", "speaker": "oliver", "channel": "speech", "text": "Can we finish the toast before we start a fight?", "scene": 1, "id": "ep01_s1_05", "next": "ep01_s1_06", "background": "bg_crimson_hall_evening", "ko": "싸움은 건배부터 끝내고 하면 안 될까?", "portrait": "oliver_standing_public_smile"}, {"kind": "line", "speaker": "chloe", "channel": "speech", "text": "Of course, darling. Smile. My father’s office follows the club account.", "scene": 1, "id": "ep01_s1_06", "next": "ep01_s1_07", "background": "bg_crimson_hall_evening", "ko": "물론이지, 자기야. 웃어. 우리 아버지 사무실이 클럽 계정을 팔로우하거든.", "portrait": "chloe_standing_host"}, {"kind": "line", "speaker": "oliver", "channel": "speech", "text": "Does he want a son-in-law or a campaign poster?", "scene": 1, "id": "ep01_s1_07", "next": "ep01_s1_08", "background": "bg_crimson_hall_evening", "ko": "아버님은 사위를 원하시는 거야, 선거 포스터를 원하시는 거야?", "portrait": "oliver_standing_weary"}, {"kind": "line", "speaker": "chloe", "channel": "speech", "text": "Tonight? Good lighting.", "scene": 1, "id": "ep01_s1_08", "next": "ep01_s1_09", "background": "bg_crimson_hall_evening", "ko": "오늘 밤엔? 조명 잘 받는 사람.", "portrait": "chloe_standing_guarded"}, {"kind": "line", "speaker": "sophie", "channel": "speech", "text": "Oliver, have some water.", "scene": 1, "id": "ep01_s1_09", "next": "ep01_s1_10", "background": "bg_crimson_hall_evening", "ko": "올리버, 물 좀 마셔.", "portrait": "sophie_standing_offer_water"}, {"kind": "line", "speaker": "oliver", "channel": "speech", "text": "I’m fine.", "scene": 1, "id": "ep01_s1_10", "next": "ep01_s1_11", "background": "bg_crimson_hall_evening", "ko": "괜찮아.", "portrait": "oliver_standing_fine"}, {"kind": "line", "speaker": "sophie", "channel": "speech", "text": "You’ve been holding an empty glass for ten minutes.", "scene": 1, "id": "ep01_s1_11", "next": "ep01_s1_12", "background": "bg_crimson_hall_evening", "ko": "빈 잔을 10분째 들고 있잖아.", "portrait": "sophie_standing_attentive"}, {"kind": "line", "speaker": "julian", "channel": "speech", "text": "She notices everything. It’s comforting until it’s about you.", "scene": 1, "id": "ep01_s1_12", "next": "ep01_s1_13", "background": "bg_crimson_hall_evening", "ko": "소피는 뭐든 다 알아채. 그게 내 얘기가 되기 전까지는 든든하지.", "portrait": "julian_standing_jealous"}, {"kind": "line", "speaker": "sophie", "channel": "speech", "text": "Your cuff is in the dip.", "scene": 1, "id": "ep01_s1_13", "next": "ep01_s1_14", "background": "bg_crimson_hall_evening", "ko": "네 소매, 소스에 빠졌어.", "portrait": "sophie_standing_dry_smile"}, {"kind": "line", "speaker": "julian", "channel": "speech", "text": "Case in point.", "scene": 1, "id": "ep01_s1_14", "next": "ep01_s1_15", "background": "bg_crimson_hall_evening", "ko": "봐, 내 말이 맞지.", "portrait": "julian_standing_embarrassed"}, {"kind": "line", "speaker": "chloe", "channel": "speech", "text": "Our new member. Tell me—are you here for the connections or the company?", "scene": 1, "directions": ["올리버는 잔을 내려놓는다. 클로이는 사용자의 명찰을 읽는다."], "id": "ep01_s1_15", "next": "ep01_c01", "background": "bg_crimson_hall_evening", "ko": "우리 신입 멤버네. 말해 봐. 인맥 때문에 온 거야, 아니면 사람들이 좋아서 온 거야?", "portrait": "chloe_standing_question"}, {"kind": "choice", "choice_id": "ep01_c01", "title_ko": "첫인상 만들기", "options": [{"id": "A", "intent_ko": "사람들을 알아가고 싶다고 편하게 답한다.", "hint_en": "I’m here to get to know people."}, {"id": "B", "intent_ko": "들어오기 힘든 모임이라 궁금했다고 솔직히 답한다.", "hint_en": "I was curious about a club that’s so hard to get into."}], "scene": 1, "id": "ep01_c01", "branch": {"A": "ep01_c01_A_1", "B": "ep01_c01_B_1"}, "rejoin": "ep01_s1_16", "next": null, "background": "bg_crimson_hall_evening"}, {"kind": "line", "speaker": "chloe", "channel": "speech", "text": "How refreshing. Someone who admits they like people.", "scene": 1, "in_branch": {"choice_id": "ep01_c01", "option": "A"}, "id": "ep01_c01_A_1", "next": "ep01_c01_A_2", "background": "bg_crimson_hall_evening", "ko": "신선하네. 사람이 좋다고 인정하는 사람이라니.", "portrait": "chloe_standing_question"}, {"kind": "line", "speaker": "ethan", "channel": "speech", "text": "Give it an hour.", "scene": 1, "in_branch": {"choice_id": "ep01_c01", "option": "A"}, "id": "ep01_c01_A_2", "next": "ep01_s1_16", "background": "bg_crimson_hall_evening", "ko": "한 시간만 지나 봐.", "portrait": "ethan_standing_dry_amusement"}, {"kind": "line", "speaker": "chloe", "channel": "speech", "text": "Exclusivity does get people’s attention.", "scene": 1, "in_branch": {"choice_id": "ep01_c01", "option": "B"}, "id": "ep01_c01_B_1", "next": "ep01_c01_B_2", "background": "bg_crimson_hall_evening", "ko": "아무나 못 들어온다는 게 사람들 관심을 끌긴 하지.", "portrait": "chloe_standing_question"}, {"kind": "line", "speaker": "julian", "channel": "speech", "text": "So does a fire alarm. We aim higher.", "scene": 1, "in_branch": {"choice_id": "ep01_c01", "option": "B"}, "id": "ep01_c01_B_2", "next": "ep01_s1_16", "background": "bg_crimson_hall_evening", "ko": "화재경보기도 관심은 끌어. 우린 목표가 더 높아.", "portrait": "julian_standing_wry"}, {"kind": "line", "speaker": "oliver", "channel": "speech", "text": "Don’t let them scare you off. They rehearse this.", "scene": 1, "id": "ep01_s1_16", "next": "ep01_s2_01", "background": "bg_crimson_hall_evening", "ko": "이 사람들 때문에 겁먹지 마. 이거 다 연습한 거야.", "portrait": "oliver_standing_accept_water"}, {"kind": "line", "speaker": "narration", "channel": "narration", "text": "Later, the six of them gather in a private lounge. Julian asks you to stay and help with the party game. Luna, a transfer student, takes the last chair.", "scene": 2, "id": "ep01_s2_01", "next": "ep01_s2_02", "background": "bg_vip_lounge_night", "ko": "잠시 후, 여섯 사람이 프라이빗 라운지에 모인다. 줄리언은 당신에게 남아서 파티 게임을 도와 달라고 한다. 편입생 루나가 마지막 남은 의자에 앉는다."}, {"kind": "line", "speaker": "luna", "channel": "speech", "text": "Is this seat taken?", "scene": 2, "id": "ep01_s2_02", "next": "ep01_s2_03", "background": "bg_vip_lounge_night", "ko": "여기 자리 있어요?", "portrait": "luna_standing_arrival"}, {"kind": "line", "speaker": "chloe", "channel": "speech", "text": "Depends. Were you invited?", "scene": 2, "id": "ep01_s2_03", "next": "ep01_s2_04", "background": "bg_vip_lounge_night", "ko": "글쎄. 초대는 받았어?", "portrait": "chloe_seated_probe"}, {"kind": "line", "speaker": "julian", "channel": "speech", "text": "By me. Try not to make that sound like a crime.", "scene": 2, "id": "ep01_s2_04", "next": "ep01_s2_05", "background": "bg_vip_lounge_night", "ko": "내가 초대했어. 무슨 범죄처럼 들리게 말하지 좀 마.", "portrait": "julian_seated_amused"}, {"kind": "line", "speaker": "sophie", "channel": "speech", "text": "The rules are simple. One question. One honest answer.", "scene": 2, "id": "ep01_s2_05", "next": "ep01_s2_06", "background": "bg_vip_lounge_night", "ko": "규칙은 간단해. 질문 하나. 솔직한 대답 하나.", "portrait": "sophie_seated_explain"}, {"kind": "line", "speaker": "ethan", "channel": "speech", "text": "And absolutely no way to verify either.", "scene": 2, "id": "ep01_s2_06", "next": "ep01_s2_07", "background": "bg_vip_lounge_night", "ko": "그리고 둘 다 확인할 방법은 전혀 없고.", "portrait": "ethan_seated_skeptical"}, {"kind": "line", "speaker": "chloe", "channel": "speech", "text": "Luna. Why did you really leave your last school?", "scene": 2, "id": "ep01_s2_07", "next": "ep01_s2_08", "background": "bg_vip_lounge_night", "ko": "루나. 전에 다니던 학교는 진짜 왜 떠난 거야?", "portrait": "chloe_seated_probe"}, {"kind": "line", "speaker": "luna", "channel": "speech", "text": "I transferred.", "scene": 2, "id": "ep01_s2_08", "next": "ep01_s2_09", "background": "bg_vip_lounge_night", "ko": "편입한 거예요.", "portrait": "luna_seated_composed"}, {"kind": "line", "speaker": "chloe", "channel": "speech", "text": "People usually have a reason. Bad grades? Someone else’s boyfriend?", "scene": 2, "id": "ep01_s2_09", "next": "ep01_s2_10", "background": "bg_vip_lounge_night", "ko": "보통은 이유가 있잖아. 성적이 나빴다든가? 남의 남자친구라든가?", "portrait": "chloe_seated_probe"}, {"kind": "line", "speaker": "luna", "channel": "speech", "text": "Do you always offer answers before you ask a question?", "scene": 2, "id": "ep01_s2_10", "next": "ep01_s2_11", "background": "bg_vip_lounge_night", "ko": "원래 질문하기 전에 답부터 정해 주는 편이에요?", "portrait": "luna_seated_challenge"}, {"kind": "line", "speaker": "chloe", "channel": "speech", "text": "Only when the truth needs encouragement.", "scene": 2, "id": "ep01_s2_11", "next": "ep01_s2_12", "background": "bg_vip_lounge_night", "ko": "진실한테 용기가 좀 필요할 때만.", "portrait": "chloe_seated_probe"}, {"kind": "line", "speaker": "luna", "channel": "speech", "text": "Is this how they welcomed you, too?", "scene": 2, "directions": ["루나는 사용자 쪽을 본다."], "id": "ep01_s2_12", "next": "ep01_c02", "background": "bg_vip_lounge_night", "ko": "당신도 이런 식으로 환영받았어요?", "portrait": "luna_seated_ask"}, {"kind": "choice", "choice_id": "ep01_c02", "title_ko": "공격적인 질문에 개입하기", "options": [{"id": "A", "intent_ko": "답하고 싶지 않으면 답하지 않아도 된다고 말한다.", "hint_en": "You don’t have to answer that if you don’t want to."}, {"id": "B", "intent_ko": "클로이에게 왜 그 질문이 중요한지 묻는다.", "hint_en": "Why does that matter to you?"}], "scene": 2, "id": "ep01_c02", "branch": {"A": "ep01_c02_A_1", "B": "ep01_c02_B_1"}, "rejoin": "ep01_s2_13", "next": null, "background": "bg_vip_lounge_night"}, {"kind": "line", "speaker": "luna", "channel": "speech", "text": "Thank you. I can answer. I just wanted to know the rules.", "scene": 2, "in_branch": {"choice_id": "ep01_c02", "option": "A"}, "id": "ep01_c02_A_1", "next": "ep01_c02_A_2", "background": "bg_vip_lounge_night", "ko": "고마워요. 대답할 수 있어요. 그냥 규칙을 알고 싶었을 뿐이에요.", "portrait": "luna_seated_trust"}, {"kind": "line", "speaker": "chloe", "channel": "speech", "text": "Apparently we’re writing new ones.", "scene": 2, "in_branch": {"choice_id": "ep01_c02", "option": "A"}, "id": "ep01_c02_A_2", "next": "ep01_s2_13", "background": "bg_vip_lounge_night", "ko": "보아하니 새 규칙을 만드는 중인가 보네.", "portrait": "chloe_seated_offended"}, {"kind": "line", "speaker": "chloe", "channel": "speech", "text": "I like to know who’s in my house.", "scene": 2, "in_branch": {"choice_id": "ep01_c02", "option": "B"}, "id": "ep01_c02_B_1", "next": "ep01_c02_B_2", "background": "bg_vip_lounge_night", "ko": "내 집에 누가 들어와 있는지는 알아야 하니까.", "portrait": "chloe_seated_offended"}, {"kind": "line", "speaker": "luna", "channel": "speech", "text": "Then you should ask what brought me here.", "scene": 2, "in_branch": {"choice_id": "ep01_c02", "option": "B"}, "id": "ep01_c02_B_2", "next": "ep01_s2_13", "background": "bg_vip_lounge_night", "ko": "그럼 제가 왜 여기 왔는지를 물어봐야죠.", "portrait": "luna_seated_challenge"}, {"kind": "line", "speaker": "luna", "channel": "speech", "text": "I came to find out why someone died—and why everyone stopped asking about it.", "scene": 2, "id": "ep01_s2_13", "next": "ep01_s2_14", "background": "bg_vip_lounge_night", "ko": "누군가가 왜 죽었는지 알아내려고 왔어요. 그리고 왜 다들 그 일을 더는 묻지 않게 됐는지도요.", "portrait": "luna_seated_reveal"}, {"kind": "line", "speaker": "oliver", "channel": "speech", "text": "Who?", "scene": 2, "id": "ep01_s2_14", "next": "ep01_s2_15", "background": "bg_vip_lounge_night", "ko": "누구?", "portrait": "oliver_seated_frozen"}, {"kind": "line", "speaker": "luna", "channel": "speech", "text": "Elena. Last year’s initiation.", "scene": 2, "id": "ep01_s2_15", "next": "ep01_s2_16", "background": "bg_vip_lounge_night", "ko": "엘레나요. 작년 신입 입회식.", "portrait": "luna_seated_reveal"}, {"kind": "line", "speaker": "sophie", "channel": "speech", "text": "That was investigated.", "scene": 2, "directions": ["올리버의 미소가 사라진다. 이든은 잔을 내려놓는다."], "id": "ep01_s2_16", "next": "ep01_s2_17", "background": "bg_vip_lounge_night", "ko": "그 일은 조사가 끝났어.", "portrait": "sophie_seated_defensive"}, {"kind": "line", "speaker": "luna", "channel": "speech", "text": "That’s not the same as explained.", "scene": 2, "id": "ep01_s2_17", "next": "ep01_s2_18", "background": "bg_vip_lounge_night", "ko": "조사했다고 해서 설명이 된 건 아니죠.", "portrait": "luna_seated_reveal"}, {"kind": "line", "speaker": "julian", "channel": "speech", "text": "Okay. We’re done with the game.", "scene": 2, "id": "ep01_s2_18", "next": "ep01_s2_19", "background": "bg_vip_lounge_night", "ko": "좋아. 게임은 여기까지.", "portrait": "julian_seated_stop"}, {"kind": "line", "speaker": "ethan", "channel": "speech", "text": "Funny. It was just getting honest.", "scene": 2, "id": "ep01_s2_19", "next": "ep01_s3_01", "background": "bg_vip_lounge_night", "ko": "웃기네. 이제 막 솔직해지려던 참인데.", "portrait": "ethan_seated_alert"}, {"kind": "line", "speaker": "narration", "channel": "narration", "text": "The room empties quickly. Luna stays behind. Through the glass doors, Chloe heads toward the terrace. Ethan follows.", "scene": 3, "id": "ep01_s3_01", "next": "ep01_s3_02", "background": "bg_lounge_corridor_night", "ko": "방은 금세 텅 빈다. 루나는 남아 있다. 유리문 너머로 클로이가 테라스 쪽으로 향하고, 이든이 그 뒤를 따른다."}, {"kind": "line", "speaker": "luna", "channel": "speech", "text": "Say a name, and suddenly nobody’s thirsty.", "scene": 3, "id": "ep01_s3_02", "next": "ep01_s3_03", "background": "bg_lounge_corridor_night", "ko": "이름 하나 꺼냈더니 갑자기 아무도 목이 안 마르네요.", "portrait": "luna_standing_observe"}, {"kind": "line", "speaker": "luna", "channel": "speech", "text": "You saw them. Was I imagining that?", "scene": 3, "id": "ep01_s3_03", "next": "ep01_c03", "background": "bg_lounge_corridor_night", "ko": "당신도 봤죠. 제가 잘못 본 거예요?", "portrait": "luna_standing_ask"}, {"kind": "choice", "choice_id": "ep01_c03", "title_ko": "관찰한 사실 말하기", "options": [{"id": "A", "intent_ko": "올리버가 엘레나의 이름에 굳었다고 말한다.", "hint_en": "Oliver went quiet when you mentioned Elena."}, {"id": "B", "intent_ko": "이든이 놀라기보다 이미 알고 있는 것처럼 보였다고 말한다.", "hint_en": "Ethan looked like he already knew something."}], "scene": 3, "id": "ep01_c03", "branch": {"A": "ep01_c03_A_1", "B": "ep01_c03_B_1"}, "rejoin": "ep01_s3_04", "next": null, "background": "bg_lounge_corridor_night"}, {"kind": "line", "speaker": "luna", "channel": "speech", "text": "Oliver. Right. I noticed his hands.", "scene": 3, "in_branch": {"choice_id": "ep01_c03", "option": "A"}, "id": "ep01_c03_A_1", "next": "ep01_c03_A_2", "background": "bg_lounge_corridor_night", "ko": "올리버. 맞아요. 저도 그 사람 손을 봤어요.", "portrait": "luna_standing_observe"}, {"kind": "line", "speaker": "luna", "channel": "speech", "text": "I’ll ask him. I won’t decide what it means yet.", "scene": 3, "in_branch": {"choice_id": "ep01_c03", "option": "A"}, "id": "ep01_c03_A_2", "next": "ep01_s3_04", "background": "bg_lounge_corridor_night", "ko": "그 사람한테 물어볼게요. 그게 무슨 뜻인지는 아직 단정하지 않을래요.", "portrait": "luna_standing_observe"}, {"kind": "line", "speaker": "luna", "channel": "speech", "text": "That’s what I thought. He didn’t ask who she was.", "scene": 3, "in_branch": {"choice_id": "ep01_c03", "option": "B"}, "id": "ep01_c03_B_1", "next": "ep01_c03_B_2", "background": "bg_lounge_corridor_night", "ko": "저도 그렇게 생각했어요. 그 사람은 엘레나가 누군지 묻지 않았어요.", "portrait": "luna_standing_observe"}, {"kind": "line", "speaker": "luna", "channel": "speech", "text": "Knowing her isn’t a crime. Pretending not to might matter.", "scene": 3, "in_branch": {"choice_id": "ep01_c03", "option": "B"}, "id": "ep01_c03_B_2", "next": "ep01_s3_04", "background": "bg_lounge_corridor_night", "ko": "그녀를 아는 건 죄가 아니에요. 하지만 모르는 척하는 건 의미가 있을 수 있죠.", "portrait": "luna_standing_observe"}, {"kind": "line", "speaker": "luna", "channel": "speech", "text": "Thanks for saying what you actually saw.", "scene": 3, "id": "ep01_s3_04", "next": "ep01_s3_05", "background": "bg_lounge_corridor_night", "ko": "실제로 본 걸 말해 줘서 고마워요.", "portrait": "luna_standing_softened"}, {"kind": "line", "speaker": "chloe", "channel": "speech", "text": "You enjoyed that.", "scene": 3, "audience": true, "directions": ["관객 전용 장면. 사용자는 이 대화를 듣지 못한다."], "id": "ep01_s3_05", "next": "ep01_s3_06", "background": "bg_terrace_night", "ko": "재밌었나 봐.", "portrait": "chloe_standing_vulnerable"}, {"kind": "line", "speaker": "ethan", "channel": "speech", "text": "You mean the part where you cornered a stranger?", "scene": 3, "audience": true, "id": "ep01_s3_06", "next": "ep01_s3_07", "background": "bg_terrace_night", "ko": "네가 처음 보는 사람을 몰아붙인 부분 말이야?", "portrait": "ethan_standing_confront"}, {"kind": "line", "speaker": "chloe", "channel": "speech", "text": "You’ve been looking at me all night.", "scene": 3, "audience": true, "id": "ep01_s3_07", "next": "ep01_s3_08", "background": "bg_terrace_night", "ko": "너 밤새 나만 보고 있었잖아.", "portrait": "chloe_standing_vulnerable"}, {"kind": "line", "speaker": "ethan", "channel": "speech", "text": "You’ve been checking.", "scene": 3, "audience": true, "id": "ep01_s3_08", "next": "ep01_s3_09", "background": "bg_terrace_night", "ko": "넌 그걸 계속 확인하고 있었고.", "portrait": "ethan_standing_intimate"}, {"kind": "line", "speaker": "chloe", "channel": "speech", "text": "Tell me to leave.", "scene": 3, "audience": true, "id": "ep01_s3_09", "next": "ep01_s3_10", "background": "bg_terrace_night", "ko": "가라고 말해.", "portrait": "chloe_standing_vulnerable"}, {"kind": "line", "speaker": "ethan", "channel": "speech", "text": "Do you want to?", "scene": 3, "audience": true, "id": "ep01_s3_10", "next": "ep01_s3_11", "background": "bg_terrace_night", "ko": "가고 싶어?", "portrait": "ethan_standing_intimate"}, {"kind": "line", "speaker": "chloe", "channel": "speech", "text": "No.", "scene": 3, "audience": true, "id": "ep01_s3_11", "next": "ep01_s3_12_beat", "background": "bg_terrace_night", "ko": "아니.", "portrait": "chloe_standing_vulnerable"}, {"kind": "beat", "id": "ep01_s3_12_beat", "scene": 3, "background": "bg_terrace_night", "audience": true, "cg": "cg_terrace_kiss", "next": "ep01_s3_12"}, {"kind": "line", "speaker": "ethan", "channel": "speech", "text": "What about Oliver?", "scene": 3, "audience": true, "directions": ["두 사람은 잠시 서로를 보고 입을 맞춘다. 이든이 먼저 물러난다."], "id": "ep01_s3_12", "next": "ep01_s3_13", "background": "bg_terrace_night", "ko": "올리버는?", "portrait": "ethan_standing_conflicted"}, {"kind": "line", "speaker": "chloe", "channel": "speech", "text": "Don’t say his name right now.", "scene": 3, "audience": true, "id": "ep01_s3_13", "next": "ep01_s4_01_beat", "background": "bg_terrace_night", "ko": "지금은 그 이름 꺼내지 마.", "portrait": "chloe_standing_defensive"}, {"kind": "beat", "id": "ep01_s4_01_beat", "scene": 4, "background": "bg_campus_morning", "blackout": true, "next": "ep01_s4_01"}, {"kind": "line", "speaker": "narration", "channel": "narration", "text": "By morning, an anonymous post on Ivy Talk has reached the whole campus.", "scene": 4, "directions": ["화면 암전."], "id": "ep01_s4_01", "next": "ep01_s4_02", "background": "bg_campus_morning", "ko": "아침이 되자, 아이비 톡에 올라온 익명 게시물이 캠퍼스 전체에 퍼져 있다."}, {"kind": "line", "speaker": "ivy_talk", "channel": "post", "text": "CRIMSON’S GOLDEN COUPLE? ASK CHLOE WHO SHE KISSED ON THE TERRACE.", "scene": 4, "id": "ep01_s4_02", "next": "ep01_s4_03", "background": "bg_campus_morning", "ko": "크림슨의 황금 커플? 클로이에게 테라스에서 누구랑 키스했는지 물어보시길.", "cg": "cg_ivy_talk_evidence"}, {"kind": "line", "speaker": "chloe", "channel": "group_chat", "text": "Nobody forwards this. We meet in twenty minutes.", "label": "GROUP CHAT — CHLOE", "scene": 4, "directions": ["사진: 테라스의 클로이와 이든. 노골적인 묘사 없이 실루엣."], "id": "ep01_s4_03", "next": "ep01_s4_04", "background": "bg_campus_morning", "ko": "아무도 이거 퍼뜨리지 마. 20분 뒤에 모여."}, {"kind": "line", "speaker": "julian", "channel": "group_chat", "text": "That should calm everyone down.", "label": "GROUP CHAT — JULIAN", "scene": 4, "id": "ep01_s4_04", "next": "ep01_s4_05", "background": "bg_campus_morning", "ko": "그러면 다들 진정되겠네."}, {"kind": "line", "speaker": "luna", "channel": "group_chat", "text": "Someone wanted this seen.", "label": "GROUP CHAT — LUNA", "scene": 4, "id": "ep01_s4_05", "next": "ep01_s4_06", "background": "bg_campus_morning", "ko": "누군가 이걸 보여 주고 싶었던 거예요."}, {"kind": "line", "speaker": "luna", "channel": "private_message", "text": "Are you coming?", "label": "PRIVATE MESSAGE — LUNA", "scene": 4, "id": "ep01_s4_06", "next": "ep01_c04", "background": "bg_campus_morning", "ko": "올 거예요?"}, {"kind": "choice", "choice_id": "ep01_c04", "title_ko": "소문을 대하는 태도", "options": [{"id": "A", "intent_ko": "사진을 더 퍼뜨리지 않고 직접 이야기를 듣겠다고 한다.", "hint_en": "I won’t share the photo. I’d rather hear from them."}, {"id": "B", "intent_ko": "비난부터 하기 전에 사진 출처를 확인하자고 한다.", "hint_en": "Let’s find out where the photo came from first."}], "scene": 4, "id": "ep01_c04", "branch": {"A": "ep01_c04_A_1", "B": "ep01_c04_B_1"}, "rejoin": "ep01_s4_07", "next": null, "background": "bg_campus_morning", "medium": "text_message"}, {"kind": "line", "speaker": "luna", "channel": "private_message", "text": "Good. An audience is the last thing they need.", "scene": 4, "in_branch": {"choice_id": "ep01_c04", "option": "A"}, "id": "ep01_c04_A_1", "next": "ep01_c04_A_2", "background": "bg_campus_morning", "ko": "좋아요. 지금 그 사람들한테 제일 필요 없는 게 구경꾼이니까요."}, {"kind": "line", "speaker": "luna", "channel": "private_message", "text": "Meet me outside the club office.", "scene": 4, "in_branch": {"choice_id": "ep01_c04", "option": "A"}, "id": "ep01_c04_A_2", "next": "ep01_s4_07", "background": "bg_campus_morning", "ko": "클럽 사무실 앞에서 만나요."}, {"kind": "line", "speaker": "luna", "channel": "private_message", "text": "Exactly. Whoever posted it picked the timing.", "scene": 4, "in_branch": {"choice_id": "ep01_c04", "option": "B"}, "id": "ep01_c04_B_1", "next": "ep01_c04_B_2", "background": "bg_campus_morning", "ko": "맞아요. 올린 사람이 타이밍을 고른 거예요."}, {"kind": "line", "speaker": "luna", "channel": "private_message", "text": "Let’s find out why.", "scene": 4, "in_branch": {"choice_id": "ep01_c04", "option": "B"}, "id": "ep01_c04_B_2", "next": "ep01_s4_07", "background": "bg_campus_morning", "ko": "왜 그랬는지 알아봐요."}, {"kind": "line", "speaker": "unknown", "channel": "private_message", "text": "You were in that room. Ask them what happened to Elena.", "label": "PRIVATE MESSAGE — UNKNOWN", "scene": 4, "id": "ep01_s4_07", "next": "ep01_s4_08", "background": "bg_campus_morning", "ko": "너는 그 방에 있었어. 그들에게 엘레나에게 무슨 일이 있었는지 물어봐."}, {"kind": "line", "speaker": "narration", "channel": "narration", "text": "The message disappears before you can reply.", "scene": 4, "id": "ep01_s4_08", "next": "ep01_s4_09", "background": "bg_campus_morning", "ko": "답장을 보내기도 전에 메시지가 사라진다."}, {"kind": "line", "speaker": "end_card", "channel": "end_card", "text": "Someone is watching. Someone wants you to watch, too.", "scene": 4, "id": "ep01_s4_09", "next": null, "background": "bg_campus_morning", "ko": "누군가 지켜보고 있다. 그리고 그 누군가는 당신도 지켜보길 바란다."}]}, "red_ivy_s1_ep02": {"story_id": "red_ivy_s1", "episode_id": "red_ivy_s1_ep02", "number": 2, "title": "The Price of Staying", "access": "free", "start": "ep02_s1_01", "scenes": [{"index": 1, "place_ko": "클럽 사무실 / 아침", "background": "bg_club_office_morning"}, {"index": 2, "place_ko": "도서관 / 늦은 저녁", "background": "bg_library_late_evening"}, {"index": 3, "place_ko": "사진관 복도", "background": "bg_darkroom_corridor"}, {"index": 4, "place_ko": "암실", "background": "bg_darkroom", "audience_background": "bg_darkroom_corridor"}], "nodes": [{"kind": "line", "speaker": "narration", "channel": "narration", "text": "Chloe has called everyone to the club office. Your name is still on last night’s guest list. That makes you a witness, whether you wanted to be one or not.", "scene": 1, "id": "ep02_s1_01", "next": "ep02_s1_02", "background": "bg_club_office_morning", "ko": "클로이가 모두를 클럽 사무실로 불러 모았다. 어젯밤 게스트 명단에는 아직 당신의 이름이 있다. 원하든 원치 않든, 당신은 목격자다."}, {"kind": "line", "speaker": "chloe", "channel": "speech", "text": "It’s a photograph. One angle. Half a second.", "scene": 1, "id": "ep02_s1_02", "next": "ep02_s1_03", "background": "bg_club_office_morning", "ko": "사진 한 장이야. 한 각도. 0.5초.", "portrait": "chloe_standing_guarded"}, {"kind": "line", "speaker": "oliver", "channel": "speech", "text": "Was it a kiss?", "scene": 1, "id": "ep02_s1_03", "next": "ep02_s1_04", "background": "bg_club_office_morning", "ko": "키스였어?", "portrait": "oliver_standing_weary"}, {"kind": "line", "speaker": "chloe", "channel": "speech", "text": "You’re letting strangers tell you what happened.", "scene": 1, "id": "ep02_s1_04", "next": "ep02_s1_05", "background": "bg_club_office_morning", "ko": "모르는 사람들이 무슨 일이 있었는지 정하게 두는 거야?", "portrait": "chloe_standing_guarded"}, {"kind": "line", "speaker": "oliver", "channel": "speech", "text": "I’m asking you.", "scene": 1, "id": "ep02_s1_05", "next": "ep02_s1_06", "background": "bg_club_office_morning", "ko": "난 너한테 묻고 있어.", "portrait": "oliver_standing_weary"}, {"kind": "line", "speaker": "ethan", "channel": "speech", "text": "Yes. It was.", "scene": 1, "id": "ep02_s1_06", "next": "ep02_s1_07", "background": "bg_club_office_morning", "ko": "맞아. 키스였어.", "portrait": "ethan_standing_confront"}, {"kind": "line", "speaker": "chloe", "channel": "speech", "text": "You don’t get to speak for me.", "scene": 1, "directions": ["클로이는 이든을 돌아본다."], "id": "ep02_s1_07", "next": "ep02_s1_08", "background": "bg_club_office_morning", "ko": "네가 날 대신해서 말할 자격은 없어.", "portrait": "chloe_standing_guarded"}, {"kind": "line", "speaker": "ethan", "channel": "speech", "text": "Then stop making me part of a lie.", "scene": 1, "id": "ep02_s1_08", "next": "ep02_s1_09", "background": "bg_club_office_morning", "ko": "그럼 날 거짓말에 끌어들이지 마.", "portrait": "ethan_standing_confront"}, {"kind": "line", "speaker": "sophie", "channel": "speech", "text": "Oliver, maybe we should talk outside.", "scene": 1, "id": "ep02_s1_09", "next": "ep02_s1_10", "background": "bg_club_office_morning", "ko": "올리버, 밖에서 얘기하는 게 좋겠어.", "portrait": "sophie_standing_watch"}, {"kind": "line", "speaker": "oliver", "channel": "speech", "text": "In a minute.", "scene": 1, "id": "ep02_s1_10", "next": "ep02_s1_11", "background": "bg_club_office_morning", "ko": "잠깐만.", "portrait": "oliver_standing_weary"}, {"kind": "line", "speaker": "julian", "channel": "speech", "text": "Whoever took it stood by the lounge window. That narrows things down.", "scene": 1, "id": "ep02_s1_11", "next": "ep02_s1_12", "background": "bg_club_office_morning", "ko": "찍은 사람은 라운지 창가에 서 있었어. 범위가 좁혀지지.", "portrait": "julian_standing_host"}, {"kind": "line", "speaker": "luna", "channel": "speech", "text": "So does asking who benefits.", "scene": 1, "id": "ep02_s1_12", "next": "ep02_s1_13", "background": "bg_club_office_morning", "ko": "누가 이득을 보는지 물어봐도 좁혀지죠.", "portrait": "luna_standing_observe"}, {"kind": "line", "speaker": "chloe", "channel": "speech", "text": "And there it is. The new girl has a theory.", "scene": 1, "id": "ep02_s1_13", "next": "ep02_s1_14", "background": "bg_club_office_morning", "ko": "나왔네. 전학생께서 가설이 있으시대.", "portrait": "chloe_standing_guarded"}, {"kind": "line", "speaker": "chloe", "channel": "speech", "text": "You were watching the door. Did you see anyone with a phone?", "scene": 1, "directions": ["사용자에게"], "id": "ep02_s1_14", "next": "ep02_c01", "background": "bg_club_office_morning", "ko": "넌 문 쪽을 보고 있었잖아. 휴대폰 든 사람 봤어?", "portrait": "chloe_standing_guarded"}, {"kind": "choice", "choice_id": "ep02_c01", "title_ko": "모르는 것을 인정하기", "options": [{"id": "A", "intent_ko": "확인하지 못한 사람을 지목할 수 없다고 말한다.", "hint_en": "I can’t point to someone when I didn’t see what happened."}, {"id": "B", "intent_ko": "사람들이 오갔지만 촬영 장면은 보지 못했다고 말한다.", "hint_en": "I saw people coming and going, but not anyone taking that photo."}], "scene": 1, "id": "ep02_c01", "branch": {"A": "ep02_c01_A_1", "B": "ep02_c01_B_1"}, "rejoin": "ep02_s1_15", "next": null, "background": "bg_club_office_morning"}, {"kind": "line", "speaker": "chloe", "channel": "speech", "text": "Convenient.", "scene": 1, "in_branch": {"choice_id": "ep02_c01", "option": "A"}, "id": "ep02_c01_A_1", "next": "ep02_c01_A_2", "background": "bg_club_office_morning", "ko": "참 편리하네.", "portrait": "chloe_standing_guarded"}, {"kind": "line", "speaker": "ethan", "channel": "speech", "text": "Accurate. Try it.", "scene": 1, "in_branch": {"choice_id": "ep02_c01", "option": "A"}, "id": "ep02_c01_A_2", "next": "ep02_s1_15", "background": "bg_club_office_morning", "ko": "정확한 거지. 너도 해 봐.", "portrait": "ethan_standing_dry_amusement"}, {"kind": "line", "speaker": "julian", "channel": "speech", "text": "Good distinction. A phone isn’t a confession.", "scene": 1, "in_branch": {"choice_id": "ep02_c01", "option": "B"}, "id": "ep02_c01_B_1", "next": "ep02_c01_B_2", "background": "bg_club_office_morning", "ko": "좋은 구분이야. 휴대폰을 들었다고 자백은 아니니까.", "portrait": "julian_standing_host"}, {"kind": "line", "speaker": "oliver", "channel": "speech", "text": "At least one person here can answer a question.", "scene": 1, "in_branch": {"choice_id": "ep02_c01", "option": "B"}, "id": "ep02_c01_B_2", "next": "ep02_s1_15", "background": "bg_club_office_morning", "ko": "적어도 여기 한 사람은 질문에 대답할 줄 아네.", "portrait": "oliver_standing_weary"}, {"kind": "line", "speaker": "oliver", "channel": "speech", "text": "We’ll talk later, Chloe. Without an audience.", "scene": 1, "id": "ep02_s1_15", "next": "ep02_s2_01", "background": "bg_club_office_morning", "ko": "나중에 얘기해, 클로이. 보는 사람 없을 때.", "portrait": "oliver_standing_weary"}, {"kind": "line", "speaker": "narration", "channel": "narration", "text": "You’re meeting Sophie for a study session. Her laptop has crashed. Chloe arrives before she can recover her paper.", "scene": 2, "id": "ep02_s2_01", "next": "ep02_s2_02", "background": "bg_library_late_evening", "ko": "소피와 함께 공부하기로 한 날. 소피의 노트북이 멈춰 버렸다. 소피가 리포트를 되살리기도 전에 클로이가 나타난다."}, {"kind": "line", "speaker": "sophie", "channel": "speech", "text": "It’s due at midnight. My scholarship review is next week.", "scene": 2, "id": "ep02_s2_02", "next": "ep02_s2_03", "background": "bg_library_late_evening", "ko": "자정까지 내야 해. 장학금 심사가 다음 주야.", "portrait": "sophie_seated_unsettled"}, {"kind": "line", "speaker": "chloe", "channel": "speech", "text": "I have a copy of last year’s top paper.", "scene": 2, "id": "ep02_s2_03", "next": "ep02_s2_04", "background": "bg_library_late_evening", "ko": "작년 최고점 리포트 사본이 있어.", "portrait": "chloe_standing_host"}, {"kind": "line", "speaker": "sophie", "channel": "speech", "text": "That isn’t my paper.", "scene": 2, "id": "ep02_s2_04", "next": "ep02_s2_05", "background": "bg_library_late_evening", "ko": "그건 내 리포트가 아니야.", "portrait": "sophie_seated_unsettled"}, {"kind": "line", "speaker": "chloe", "channel": "speech", "text": "It’s a starting point.", "scene": 2, "id": "ep02_s2_05", "next": "ep02_s2_06", "background": "bg_library_late_evening", "ko": "출발점이지.", "portrait": "chloe_standing_host"}, {"kind": "line", "speaker": "sophie", "channel": "speech", "text": "What do you want?", "scene": 2, "id": "ep02_s2_06", "next": "ep02_s2_07", "background": "bg_library_late_evening", "ko": "원하는 게 뭐야?", "portrait": "sophie_seated_unsettled"}, {"kind": "line", "speaker": "chloe", "channel": "speech", "text": "Stay close to Oliver. Keep him occupied. Find out what Luna knows.", "scene": 2, "id": "ep02_s2_07", "next": "ep02_s2_08", "background": "bg_library_late_evening", "ko": "올리버 곁에 있어. 딴생각 못 하게 하고. 루나가 뭘 아는지 알아내.", "portrait": "chloe_standing_host"}, {"kind": "line", "speaker": "sophie", "channel": "speech", "text": "Ask her yourself.", "scene": 2, "id": "ep02_s2_08", "next": "ep02_s2_09", "background": "bg_library_late_evening", "ko": "직접 물어봐.", "portrait": "sophie_seated_unsettled"}, {"kind": "line", "speaker": "chloe", "channel": "speech", "text": "Does your roommate know you still have the messages about taking your exam for you?", "scene": 2, "id": "ep02_s2_09", "next": "ep02_s2_10", "background": "bg_library_late_evening", "ko": "네 룸메이트는 알아? 시험을 대신 쳐 달라고 한 메시지를 네가 아직 갖고 있다는 거.", "portrait": "chloe_standing_guarded"}, {"kind": "line", "speaker": "sophie", "channel": "speech", "text": "Keep your voice down.", "scene": 2, "directions": ["소피가 노트북을 닫는다."], "id": "ep02_s2_10", "next": "ep02_s2_11", "background": "bg_library_late_evening", "ko": "목소리 낮춰.", "portrait": "sophie_seated_defensive"}, {"kind": "line", "speaker": "chloe", "channel": "speech", "text": "Then give me a reason to.", "scene": 2, "id": "ep02_s2_11", "next": "ep02_s2_12", "background": "bg_library_late_evening", "ko": "그럼 그럴 이유를 줘.", "portrait": "chloe_standing_guarded"}, {"kind": "line", "speaker": "sophie", "channel": "speech", "text": "You heard enough. Go ahead. Tell me I’m pathetic.", "scene": 2, "directions": ["클로이는 자료가 담긴 봉투를 놓고 떠난다. 소피가 사용자를 본다."], "id": "ep02_s2_12", "next": "ep02_c02", "background": "bg_library_late_evening", "ko": "충분히 들었지. 해 봐. 내가 한심하다고.", "portrait": "sophie_seated_unsettled"}, {"kind": "choice", "choice_id": "ep02_c02", "title_ko": "판단하지 않고 대응하기", "options": [{"id": "A", "intent_ko": "협박을 받아들일 필요는 없다고 말한다.", "hint_en": "You don’t have to do what she wants just because she threatened you."}, {"id": "B", "intent_ko": "지금 가장 도움이 되는 일이 무엇인지 묻는다.", "hint_en": "What would help you most right now?"}], "scene": 2, "id": "ep02_c02", "branch": {"A": "ep02_c02_A_1", "B": "ep02_c02_B_1"}, "rejoin": "ep02_s2_13", "next": null, "background": "bg_library_late_evening"}, {"kind": "line", "speaker": "sophie", "channel": "speech", "text": "She isn’t making up the exam. That’s the problem.", "scene": 2, "in_branch": {"choice_id": "ep02_c02", "option": "A"}, "id": "ep02_c02_A_1", "next": "ep02_c02_A_2", "background": "bg_library_late_evening", "ko": "시험 얘기는 지어낸 게 아니야. 그게 문제야.", "portrait": "sophie_seated_defensive"}, {"kind": "line", "speaker": "sophie", "channel": "speech", "text": "I made one awful decision. She’s trying to make it a subscription.", "scene": 2, "in_branch": {"choice_id": "ep02_c02", "option": "A"}, "id": "ep02_c02_A_2", "next": "ep02_s2_13", "background": "bg_library_late_evening", "ko": "끔찍한 결정 한 번 했을 뿐인데, 클로이는 그걸 정기 구독으로 만들려고 해.", "portrait": "sophie_seated_defensive"}, {"kind": "line", "speaker": "sophie", "channel": "speech", "text": "Sit here while I email my professor.", "scene": 2, "in_branch": {"choice_id": "ep02_c02", "option": "B"}, "id": "ep02_c02_B_1", "next": "ep02_c02_B_2", "background": "bg_library_late_evening", "ko": "교수님께 메일 쓰는 동안 여기 있어 줘.", "portrait": "sophie_seated_explain"}, {"kind": "line", "speaker": "sophie", "channel": "speech", "text": "I need one thing tonight that isn’t another lie.", "scene": 2, "in_branch": {"choice_id": "ep02_c02", "option": "B"}, "id": "ep02_c02_B_2", "next": "ep02_s2_13", "background": "bg_library_late_evening", "ko": "오늘 밤엔 거짓말이 아닌 게 하나라도 필요해.", "portrait": "sophie_seated_explain"}, {"kind": "line", "speaker": "sophie", "channel": "speech", "text": "I’m not using that paper. Whatever happens next, that part is mine.", "scene": 2, "id": "ep02_s2_13", "next": "ep02_s3_01", "background": "bg_library_late_evening", "ko": "그 리포트는 안 쓸 거야. 앞으로 무슨 일이 생기든, 그건 내가 정한 거야.", "portrait": "sophie_seated_explain"}, {"kind": "line", "speaker": "narration", "channel": "narration", "text": "Luna asks you to come with her to Ethan’s campus darkroom. He photographed last year’s club events.", "scene": 3, "id": "ep02_s3_01", "next": "ep02_s3_02", "background": "bg_darkroom_corridor", "ko": "루나가 이든의 캠퍼스 암실에 같이 가 달라고 한다. 이든은 작년 클럽 행사 사진을 찍었다."}, {"kind": "line", "speaker": "luna", "channel": "speech", "text": "He knew Elena. I want to hear him say it.", "scene": 3, "id": "ep02_s3_02", "next": "ep02_s3_03", "background": "bg_darkroom_corridor", "ko": "그 사람은 엘레나를 알았어요. 본인 입으로 듣고 싶어요.", "portrait": "luna_standing_observe"}, {"kind": "line", "speaker": "ethan", "channel": "speech", "text": "The darkroom’s closed.", "scene": 3, "directions": ["이든이 문을 연다."], "id": "ep02_s3_03", "next": "ep02_s3_04", "background": "bg_darkroom_corridor", "ko": "암실 문 닫았어.", "portrait": "ethan_standing_detached"}, {"kind": "line", "speaker": "luna", "channel": "speech", "text": "Then we can talk without an audience.", "scene": 3, "id": "ep02_s3_04", "next": "ep02_s3_05", "background": "bg_darkroom_corridor", "ko": "그럼 보는 사람 없이 얘기할 수 있겠네.", "portrait": "luna_standing_observe"}, {"kind": "line", "speaker": "ethan", "channel": "speech", "text": "You brought one.", "scene": 3, "id": "ep02_s3_05", "next": "ep02_s3_06", "background": "bg_darkroom_corridor", "ko": "한 명 데려왔잖아.", "portrait": "ethan_standing_detached"}, {"kind": "line", "speaker": "luna", "channel": "speech", "text": "I brought someone who doesn’t owe this club anything.", "scene": 3, "id": "ep02_s3_06", "next": "ep02_s3_07", "background": "bg_darkroom_corridor", "ko": "이 클럽에 빚진 게 없는 사람을 데려왔어.", "portrait": "luna_standing_observe"}, {"kind": "line", "speaker": "luna", "channel": "speech", "text": "Where did you get that?", "scene": 3, "directions": ["루나가 게시판 속 엘레나 사진을 발견한다."], "id": "ep02_s3_07", "next": "ep02_s3_08", "background": "bg_darkroom_corridor", "ko": "그거 어디서 났어?", "portrait": "luna_standing_observe"}, {"kind": "line", "speaker": "ethan", "channel": "speech", "text": "I took it.", "scene": 3, "id": "ep02_s3_08", "next": "ep02_s3_09", "background": "bg_darkroom_corridor", "ko": "내가 찍었어.", "portrait": "ethan_standing_detached"}, {"kind": "line", "speaker": "luna", "channel": "speech", "text": "She hated that jacket. She only wore it when she was nervous.", "scene": 3, "id": "ep02_s3_09", "next": "ep02_s3_10", "background": "bg_darkroom_corridor", "ko": "언니는 그 재킷 싫어했어. 긴장할 때만 입었지.", "portrait": "luna_standing_observe"}, {"kind": "line", "speaker": "ethan", "channel": "speech", "text": "How would you know?", "scene": 3, "id": "ep02_s3_10", "next": "ep02_s3_11", "background": "bg_darkroom_corridor", "ko": "네가 그걸 어떻게 알아?", "portrait": "ethan_standing_detached"}, {"kind": "line", "speaker": "luna", "channel": "speech", "text": "She was my sister.", "scene": 3, "id": "ep02_s3_11", "next": "ep02_s3_12", "background": "bg_darkroom_corridor", "ko": "우리 언니였으니까.", "portrait": "luna_standing_softened"}, {"kind": "line", "speaker": "ethan", "channel": "speech", "text": "Luna—", "scene": 3, "directions": ["침묵."], "id": "ep02_s3_12", "next": "ep02_s3_13", "background": "bg_darkroom_corridor", "ko": "루나—", "portrait": "ethan_standing_conflicted"}, {"kind": "line", "speaker": "luna", "channel": "speech", "text": "Don’t. Not until you tell me what you know.", "scene": 3, "id": "ep02_s3_13", "next": "ep02_c03", "background": "bg_darkroom_corridor", "ko": "그만. 아는 걸 말하기 전까진.", "portrait": "luna_standing_observe"}, {"kind": "choice", "choice_id": "ep02_c03", "title_ko": "대화를 이어갈 방법", "options": [{"id": "A", "intent_ko": "이든에게 처음부터 차분히 설명해 달라고 한다.", "hint_en": "Could you start from the beginning?"}, {"id": "B", "intent_ko": "루나에게 잠깐 멈추고 싶은지 확인한다.", "hint_en": "Do you want to take a minute?"}], "scene": 3, "id": "ep02_c03", "branch": {"A": "ep02_c03_A_1", "B": "ep02_c03_B_1"}, "rejoin": "ep02_s3_14", "next": null, "background": "bg_darkroom_corridor"}, {"kind": "line", "speaker": "ethan", "channel": "speech", "text": "Not in the hallway. Come inside.", "scene": 3, "in_branch": {"choice_id": "ep02_c03", "option": "A"}, "id": "ep02_c03_A_1", "next": "ep02_c03_A_2", "background": "bg_darkroom_corridor", "ko": "복도에선 안 돼. 들어와.", "portrait": "ethan_standing_conflicted"}, {"kind": "line", "speaker": "luna", "channel": "speech", "text": "And don’t leave anything out to protect me.", "scene": 3, "in_branch": {"choice_id": "ep02_c03", "option": "A"}, "id": "ep02_c03_A_2", "next": "ep02_s3_14", "background": "bg_darkroom_corridor", "ko": "그리고 날 보호한다고 빼놓지 마.", "portrait": "luna_standing_observe"}, {"kind": "line", "speaker": "luna", "channel": "speech", "text": "No. I’ve spent a year waiting for someone to answer.", "scene": 3, "in_branch": {"choice_id": "ep02_c03", "option": "B"}, "id": "ep02_c03_B_1", "next": "ep02_c03_B_2", "background": "bg_darkroom_corridor", "ko": "아뇨. 누군가 대답해 주길 1년이나 기다렸어요.", "portrait": "luna_standing_observe"}, {"kind": "line", "speaker": "ethan", "channel": "speech", "text": "Then you deserve an answer.", "scene": 3, "in_branch": {"choice_id": "ep02_c03", "option": "B"}, "id": "ep02_c03_B_2", "next": "ep02_s3_14", "background": "bg_darkroom_corridor", "ko": "그럼 대답을 들을 자격이 있지.", "portrait": "ethan_standing_conflicted"}, {"kind": "line", "speaker": "ethan", "channel": "speech", "text": "I saw someone with her on the roof. I couldn’t see his face.", "scene": 3, "id": "ep02_s3_14", "next": "ep02_s3_15", "background": "bg_darkroom_corridor", "ko": "옥상에서 누군가 엘레나랑 같이 있는 걸 봤어. 얼굴은 못 봤고.", "portrait": "ethan_standing_conflicted"}, {"kind": "line", "speaker": "luna", "channel": "speech", "text": "And you said nothing?", "scene": 3, "id": "ep02_s3_15", "next": "ep02_s3_16", "background": "bg_darkroom_corridor", "ko": "그런데 아무 말도 안 했어?", "portrait": "luna_standing_observe"}, {"kind": "line", "speaker": "ethan", "channel": "speech", "text": "I gave a statement. It disappeared from the file.", "scene": 3, "id": "ep02_s3_16", "next": "ep02_s4_01", "background": "bg_darkroom_corridor", "ko": "진술했어. 그게 기록에서 사라졌지.", "portrait": "ethan_standing_conflicted"}, {"kind": "line", "speaker": "ethan", "channel": "speech", "text": "Someone’s set the corridor lock.", "scene": 4, "directions": ["문밖에서 잠금 소리. 이든이 문손잡이를 확인한다."], "id": "ep02_s4_01", "next": "ep02_s4_02", "background": "bg_darkroom", "ko": "누가 복도 잠금을 걸었어.", "portrait": "ethan_standing_confront"}, {"kind": "line", "speaker": "luna", "channel": "speech", "text": "Can you open it from here?", "scene": 4, "id": "ep02_s4_02", "next": "ep02_s4_03", "background": "bg_darkroom", "ko": "안에서 열 수 있어?", "portrait": "luna_standing_observe"}, {"kind": "line", "speaker": "ethan", "channel": "speech", "text": "Normally. Not tonight.", "scene": 4, "id": "ep02_s4_03", "next": "ep02_s4_04", "background": "bg_darkroom", "ko": "평소엔. 오늘은 아니야.", "portrait": "ethan_standing_confront"}, {"kind": "line", "speaker": "ethan", "channel": "speech", "text": "I’m calling campus security. We’re not waiting for whoever did this to change their mind.", "scene": 4, "directions": ["통신은 가능하지만 건물 출입 담당자가 다른 구역에 있다."], "id": "ep02_s4_04", "next": "ep02_s4_05", "background": "bg_darkroom", "ko": "캠퍼스 보안팀에 전화할게. 이런 짓 한 사람이 마음 바꾸길 기다릴 순 없어.", "portrait": "ethan_standing_confront"}, {"kind": "line", "speaker": "luna", "channel": "speech", "text": "They know why I’m here.", "scene": 4, "directions": ["루나는 문을 응시한다."], "id": "ep02_s4_05", "next": "ep02_c04", "background": "bg_darkroom", "ko": "그 사람들, 내가 왜 여기 왔는지 알아.", "portrait": "luna_standing_observe"}, {"kind": "choice", "choice_id": "ep02_c04", "title_ko": "루나를 안정시키기", "options": [{"id": "A", "intent_ko": "혼자가 아니며 함께 있겠다고 말한다.", "hint_en": "You’re not alone. I’ll stay with you."}, {"id": "B", "intent_ko": "지금 아는 사실과 추측을 나눠 정리하자고 한다.", "hint_en": "Let’s separate what we know from what we’re guessing."}], "scene": 4, "id": "ep02_c04", "branch": {"A": "ep02_c04_A_1", "B": "ep02_c04_B_1"}, "rejoin": "ep02_s4_06", "next": null, "background": "bg_darkroom"}, {"kind": "line", "speaker": "luna", "channel": "speech", "text": "Then stay where I can see you. Both of you.", "scene": 4, "in_branch": {"choice_id": "ep02_c04", "option": "A"}, "id": "ep02_c04_A_1", "next": "ep02_c04_A_2", "background": "bg_darkroom", "ko": "그럼 내 눈에 보이는 데 있어. 둘 다.", "portrait": "luna_standing_observe"}, {"kind": "line", "speaker": "ethan", "channel": "speech", "text": "We’re here.", "scene": 4, "in_branch": {"choice_id": "ep02_c04", "option": "A"}, "id": "ep02_c04_A_2", "next": "ep02_s4_06", "background": "bg_darkroom", "ko": "우리 여기 있어.", "portrait": "ethan_standing_confront"}, {"kind": "line", "speaker": "luna", "channel": "speech", "text": "Fact: someone locked the door. Guess: they know about Elena.", "scene": 4, "in_branch": {"choice_id": "ep02_c04", "option": "B"}, "id": "ep02_c04_B_1", "next": "ep02_c04_B_2", "background": "bg_darkroom", "ko": "사실: 누군가 문을 잠갔다. 추측: 그 사람은 엘레나 일을 안다.", "portrait": "luna_standing_observe"}, {"kind": "line", "speaker": "ethan", "channel": "speech", "text": "Good. One problem at a time.", "scene": 4, "in_branch": {"choice_id": "ep02_c04", "option": "B"}, "id": "ep02_c04_B_2", "next": "ep02_s4_06", "background": "bg_darkroom", "ko": "좋아. 한 번에 하나씩.", "portrait": "ethan_standing_confront"}, {"kind": "line", "speaker": "chloe", "channel": "speech", "text": "Pick up, Ethan.", "scene": 4, "audience": true, "directions": ["관객 전용: 복도 반대편에서 클로이가 방문자용 출입 카드를 주머니에 넣는다."], "id": "ep02_s4_06", "next": "ep02_s4_07", "background": "bg_darkroom_corridor", "ko": "받아, 이든.", "portrait": "chloe_standing_guarded"}, {"kind": "line", "speaker": "end_card", "channel": "end_card", "text": "The door isn’t the only thing keeping them trapped.", "scene": 4, "audience": true, "directions": ["이든의 휴대폰에 클로이의 전화가 뜬다."], "id": "ep02_s4_07", "next": null, "background": "bg_darkroom_corridor", "ko": "그들을 가두고 있는 건 문만이 아니다."}]}, "red_ivy_s1_ep03": {"story_id": "red_ivy_s1", "episode_id": "red_ivy_s1_ep03", "number": 3, "title": "What We Owe the Dead", "access": "free", "start": "ep03_s1_01", "scenes": [{"index": 1, "place_ko": "암실 / 구조를 기다리는 동안", "background": "bg_darkroom"}, {"index": 2, "place_ko": "암실 / 관계의 진실", "background": "bg_darkroom"}, {"index": 3, "place_ko": "조정부 라커룸 앞", "background": "bg_rowing_locker_corridor"}, {"index": 4, "place_ko": "기숙사 복도 / 저녁", "background": "bg_dorm_corridor_evening"}], "nodes": [{"kind": "line", "speaker": "narration", "channel": "narration", "text": "Campus security is on its way. Ethan turns on the work light. In the sudden brightness, Luna looks less angry than exhausted.", "scene": 1, "id": "ep03_s1_01", "next": "ep03_s1_02", "background": "bg_darkroom", "ko": "캠퍼스 보안팀이 오는 중이다. 이든이 작업등을 켠다. 갑자기 밝아진 불빛 아래, 루나는 화가 났다기보다 지쳐 보인다."}, {"kind": "line", "speaker": "luna", "channel": "speech", "text": "You had a year to find me.", "scene": 1, "id": "ep03_s1_02", "next": "ep03_s1_03", "background": "bg_darkroom", "ko": "날 찾을 시간이 1년이나 있었잖아.", "portrait": "luna_standing_observe"}, {"kind": "line", "speaker": "ethan", "channel": "speech", "text": "I didn’t know she had a sister. Your family’s name was kept out of the reports.", "scene": 1, "id": "ep03_s1_03", "next": "ep03_s1_04", "background": "bg_darkroom", "ko": "엘레나한테 동생이 있는 줄 몰랐어. 보고서엔 너희 가족 이름이 빠져 있었어.", "portrait": "ethan_standing_conflicted"}, {"kind": "line", "speaker": "luna", "channel": "speech", "text": "I use my mother’s surname. Elena used our father’s.", "scene": 1, "id": "ep03_s1_04", "next": "ep03_s1_05", "background": "bg_darkroom", "ko": "난 엄마 성을 써. 엘레나는 아빠 성을 썼고.", "portrait": "luna_standing_observe"}, {"kind": "line", "speaker": "ethan", "channel": "speech", "text": "I’m sorry.", "scene": 1, "id": "ep03_s1_05", "next": "ep03_s1_06", "background": "bg_darkroom", "ko": "미안해.", "portrait": "ethan_standing_conflicted"}, {"kind": "line", "speaker": "luna", "channel": "speech", "text": "Sorry for what? Be specific.", "scene": 1, "id": "ep03_s1_06", "next": "ep03_s1_07", "background": "bg_darkroom", "ko": "뭐가 미안한데? 정확히 말해.", "portrait": "luna_standing_observe"}, {"kind": "line", "speaker": "ethan", "channel": "speech", "text": "For believing the first person who told me to leave it alone.", "scene": 1, "id": "ep03_s1_07", "next": "ep03_s1_08", "background": "bg_darkroom", "ko": "그냥 덮어 두라고 한 첫 사람 말을 믿은 거.", "portrait": "ethan_standing_conflicted"}, {"kind": "line", "speaker": "ethan", "channel": "speech", "text": "I saw a man grab her arm. Then I lost sight of them. I heard the fall.", "scene": 1, "id": "ep03_s1_08", "next": "ep03_s1_09", "background": "bg_darkroom", "ko": "어떤 남자가 엘레나 팔을 잡는 걸 봤어. 그러고 둘을 놓쳤어. 그다음 떨어지는 소리를 들었고.", "portrait": "ethan_standing_conflicted"}, {"kind": "line", "speaker": "luna", "channel": "speech", "text": "Oliver?", "scene": 1, "id": "ep03_s1_09", "next": "ep03_s1_10", "background": "bg_darkroom", "ko": "올리버?", "portrait": "luna_standing_observe"}, {"kind": "line", "speaker": "ethan", "channel": "speech", "text": "I thought so. His coat. His build. I never saw a face.", "scene": 1, "id": "ep03_s1_10", "next": "ep03_s1_11", "background": "bg_darkroom", "ko": "그런 줄 알았어. 코트도, 체격도. 얼굴은 끝내 못 봤어.", "portrait": "ethan_standing_conflicted"}, {"kind": "line", "speaker": "luna", "channel": "speech", "text": "You let a guess sit there for a year.", "scene": 1, "id": "ep03_s1_11", "next": "ep03_s1_12", "background": "bg_darkroom", "ko": "추측을 1년 동안 그냥 내버려 둔 거네.", "portrait": "luna_standing_observe"}, {"kind": "line", "speaker": "ethan", "channel": "speech", "text": "I know.", "scene": 1, "id": "ep03_s1_12", "next": "ep03_c01", "background": "bg_darkroom", "ko": "알아.", "portrait": "ethan_standing_conflicted"}, {"kind": "choice", "choice_id": "ep03_c01", "title_ko": "목격 정보 확인하기", "options": [{"id": "A", "intent_ko": "직접 본 것과 나중에 들은 것을 구분해 달라고 한다.", "hint_en": "Which parts did you see yourself, and which parts did someone tell you?"}, {"id": "B", "intent_ko": "처음 진술을 했다는 기록이 남아 있는지 묻는다.", "hint_en": "Do you still have any record of giving that statement?"}], "scene": 1, "id": "ep03_c01", "branch": {"A": "ep03_c01_A_1", "B": "ep03_c01_B_1"}, "rejoin": "ep03_s1_13", "next": null, "background": "bg_darkroom"}, {"kind": "line", "speaker": "ethan", "channel": "speech", "text": "I saw the coat. I heard people say Oliver had been upstairs. Those are different things.", "scene": 1, "in_branch": {"choice_id": "ep03_c01", "option": "A"}, "id": "ep03_c01_A_1", "next": "ep03_c01_A_2", "background": "bg_darkroom", "ko": "난 코트를 봤어. 올리버가 위층에 있었다는 건 사람들한테 들은 거고. 그 둘은 다른 얘기야.", "portrait": "ethan_standing_conflicted"}, {"kind": "line", "speaker": "luna", "channel": "speech", "text": "From now on, keep them different.", "scene": 1, "in_branch": {"choice_id": "ep03_c01", "option": "A"}, "id": "ep03_c01_A_2", "next": "ep03_s1_13", "background": "bg_darkroom", "ko": "이제부턴 그 둘을 섞지 마.", "portrait": "luna_standing_observe"}, {"kind": "line", "speaker": "ethan", "channel": "speech", "text": "An appointment email. And the draft I wrote that morning.", "scene": 1, "in_branch": {"choice_id": "ep03_c01", "option": "B"}, "id": "ep03_c01_B_1", "next": "ep03_c01_B_2", "background": "bg_darkroom", "ko": "면담 약속 메일. 그리고 그날 아침에 써 둔 초안.", "portrait": "ethan_standing_conflicted"}, {"kind": "line", "speaker": "luna", "channel": "speech", "text": "Keep both. Not just the version you remember now.", "scene": 1, "in_branch": {"choice_id": "ep03_c01", "option": "B"}, "id": "ep03_c01_B_2", "next": "ep03_s1_13", "background": "bg_darkroom", "ko": "둘 다 보관해. 지금 기억나는 버전만 말고.", "portrait": "luna_standing_observe"}, {"kind": "line", "speaker": "ethan", "channel": "speech", "text": "Chloe has something else. A signed agreement. Her father’s office paid to keep the roof camera footage out of the internal review.", "scene": 1, "id": "ep03_s1_13", "next": "ep03_s1_14", "background": "bg_darkroom", "ko": "클로이한테 다른 게 있어. 서명된 합의서. 클로이 아버지 사무실이 돈을 내고 옥상 카메라 영상을 내부 조사에서 빼 버렸어.", "portrait": "ethan_standing_conflicted"}, {"kind": "line", "speaker": "luna", "channel": "speech", "text": "How do you know?", "scene": 1, "id": "ep03_s1_14", "next": "ep03_s1_15", "background": "bg_darkroom", "ko": "그걸 어떻게 알아?", "portrait": "luna_standing_observe"}, {"kind": "line", "speaker": "ethan", "channel": "speech", "text": "She showed me the envelope when she was drunk. Then put it in her safe.", "scene": 1, "id": "ep03_s1_15", "next": "ep03_s2_01", "background": "bg_darkroom", "ko": "취했을 때 그 봉투를 보여 줬어. 그러고는 금고에 넣었지.", "portrait": "ethan_standing_conflicted"}, {"kind": "line", "speaker": "luna", "channel": "speech", "text": "So you’re using her.", "scene": 2, "id": "ep03_s2_01", "next": "ep03_s2_02", "background": "bg_darkroom", "ko": "그러니까 클로이를 이용하고 있는 거네.", "portrait": "luna_standing_observe"}, {"kind": "line", "speaker": "ethan", "channel": "speech", "text": "I stayed close to get the document.", "scene": 2, "id": "ep03_s2_02", "next": "ep03_s2_03", "background": "bg_darkroom", "ko": "그 문서를 얻으려고 곁에 있었어.", "portrait": "ethan_standing_conflicted"}, {"kind": "line", "speaker": "luna", "channel": "speech", "text": "And kissing her was research?", "scene": 2, "id": "ep03_s2_03", "next": "ep03_s2_04", "background": "bg_darkroom", "ko": "키스도 조사였어?", "portrait": "luna_standing_observe"}, {"kind": "line", "speaker": "ethan", "channel": "speech", "text": "No. That was selfish. I’m not asking you to make it noble.", "scene": 2, "directions": ["이든은 즉시 답하지 못한다."], "id": "ep03_s2_04", "next": "ep03_s2_05", "background": "bg_darkroom", "ko": "아니. 그건 이기적이었어. 그걸 좋게 봐 달라는 건 아니야.", "portrait": "ethan_standing_conflicted"}, {"kind": "line", "speaker": "luna", "channel": "speech", "text": "Good. Because I won’t.", "scene": 2, "id": "ep03_s2_05", "next": "ep03_s2_06", "background": "bg_darkroom", "ko": "다행이네. 그럴 생각 없으니까.", "portrait": "luna_standing_observe"}, {"kind": "line", "speaker": "luna", "channel": "speech", "text": "Elena kept calling me that week. I thought she wanted money.", "scene": 2, "directions": ["루나가 의자에 앉는다."], "id": "ep03_s2_06", "next": "ep03_s2_07", "background": "bg_darkroom", "ko": "그 주에 언니가 계속 전화했어. 돈 달라는 줄 알았어.", "portrait": "luna_seated_reveal"}, {"kind": "line", "speaker": "ethan", "channel": "speech", "text": "You didn’t know.", "scene": 2, "id": "ep03_s2_07", "next": "ep03_s2_08", "background": "bg_darkroom", "ko": "넌 몰랐잖아.", "portrait": "ethan_standing_conflicted"}, {"kind": "line", "speaker": "luna", "channel": "speech", "text": "I keep hearing that. It doesn’t help.", "scene": 2, "id": "ep03_s2_08", "next": "ep03_c02", "background": "bg_darkroom", "ko": "다들 그렇게 말해. 위로가 안 돼.", "portrait": "luna_seated_reveal"}, {"kind": "choice", "choice_id": "ep03_c02", "title_ko": "죄책감에 반응하기", "options": [{"id": "A", "intent_ko": "지금 당장 괜찮아질 필요는 없다고 말한다.", "hint_en": "You don’t have to be okay right now."}, {"id": "B", "intent_ko": "엘레나에 대해 기억하고 싶은 이야기를 물어본다.", "hint_en": "What’s something about Elena you’d like us to know?"}], "scene": 2, "id": "ep03_c02", "branch": {"A": "ep03_c02_A_1", "B": "ep03_c02_B_1"}, "rejoin": "ep03_s2_09", "next": null, "background": "bg_darkroom"}, {"kind": "line", "speaker": "luna", "channel": "speech", "text": "Thank you. I’m tired of people trying to finish this feeling for me.", "scene": 2, "in_branch": {"choice_id": "ep03_c02", "option": "A"}, "id": "ep03_c02_A_1", "next": "ep03_c02_A_2", "background": "bg_darkroom", "ko": "고마워요. 사람들이 이 감정을 대신 정리해 주려는 게 지쳤어요.", "portrait": "luna_seated_composed"}, {"kind": "line", "speaker": "ethan", "channel": "speech", "text": "We can just sit here.", "scene": 2, "in_branch": {"choice_id": "ep03_c02", "option": "A"}, "id": "ep03_c02_A_2", "next": "ep03_s2_09", "background": "bg_darkroom", "ko": "그냥 여기 앉아 있어도 돼.", "portrait": "ethan_standing_conflicted"}, {"kind": "line", "speaker": "luna", "channel": "speech", "text": "She laughed before she finished a joke. You had to wait for the ending.", "scene": 2, "in_branch": {"choice_id": "ep03_c02", "option": "B"}, "id": "ep03_c02_B_1", "next": "ep03_c02_B_2", "background": "bg_darkroom", "ko": "언니는 농담을 끝내기도 전에 먼저 웃었어요. 끝까지 들으려면 기다려야 했죠.", "portrait": "luna_seated_composed"}, {"kind": "line", "speaker": "ethan", "channel": "speech", "text": "Every time. Even when the joke was terrible.", "scene": 2, "in_branch": {"choice_id": "ep03_c02", "option": "B"}, "id": "ep03_c02_B_2", "next": "ep03_s2_09", "background": "bg_darkroom", "ko": "매번 그랬지. 농담이 형편없을 때도.", "portrait": "ethan_standing_conflicted"}, {"kind": "line", "speaker": "security", "channel": "speech", "text": "Everybody okay? We’ll need statements about the lock.", "scene": 2, "directions": ["문이 열린다. 보안 직원의 화면 밖 목소리."], "id": "ep03_s2_09", "next": "ep03_s2_10", "background": "bg_darkroom", "ko": "다들 괜찮아요? 잠금 건에 대해 진술이 필요합니다."}, {"kind": "line", "speaker": "ethan", "channel": "speech", "text": "You’ll get them.", "scene": 2, "id": "ep03_s2_10", "next": "ep03_s2_11", "background": "bg_darkroom", "ko": "드릴게요.", "portrait": "ethan_standing_conflicted"}, {"kind": "line", "speaker": "luna", "channel": "speech", "text": "I don’t trust you yet.", "scene": 2, "directions": ["복도에서 루나와 이든이 잠깐 마주 본다."], "id": "ep03_s2_11", "next": "ep03_s2_12", "background": "bg_darkroom", "ko": "아직 널 믿진 않아.", "portrait": "luna_standing_observe"}, {"kind": "line", "speaker": "ethan", "channel": "speech", "text": "Fair.", "scene": 2, "id": "ep03_s2_12", "next": "ep03_s2_13", "background": "bg_darkroom", "ko": "그럴 만해.", "portrait": "ethan_standing_conflicted"}, {"kind": "line", "speaker": "luna", "channel": "speech", "text": "But don’t disappear.", "scene": 2, "id": "ep03_s2_13", "next": "ep03_s2_14", "background": "bg_darkroom", "ko": "그래도 사라지진 마.", "portrait": "luna_standing_softened"}, {"kind": "line", "speaker": "ethan", "channel": "speech", "text": "I won’t.", "scene": 2, "id": "ep03_s2_14", "next": "ep03_s3_01", "background": "bg_darkroom", "ko": "안 사라져.", "portrait": "ethan_standing_conflicted"}, {"kind": "line", "speaker": "narration", "channel": "narration", "text": "The next afternoon, Sophie asks you to wait outside while she checks on Oliver. He leaves the door open.", "scene": 3, "directions": ["이번 회차에서는 키스하지 않는다. 신뢰 회복이 먼저 시작된다."], "id": "ep03_s3_01", "next": "ep03_s3_02", "background": "bg_rowing_locker_corridor", "ko": "다음 날 오후, 소피는 올리버를 살피는 동안 밖에서 기다려 달라고 한다. 올리버는 문을 열어 둔다."}, {"kind": "line", "speaker": "oliver", "channel": "speech", "text": "Did Chloe send you?", "scene": 3, "id": "ep03_s3_02", "next": "ep03_s3_03", "background": "bg_rowing_locker_corridor", "ko": "클로이가 보냈어?", "portrait": "oliver_standing_weary"}, {"kind": "line", "speaker": "sophie", "channel": "speech", "text": "Yes.", "scene": 3, "id": "ep03_s3_03", "next": "ep03_s3_04", "background": "bg_rowing_locker_corridor", "ko": "응."}, {"kind": "line", "speaker": "oliver", "channel": "speech", "text": "At least you said it.", "scene": 3, "id": "ep03_s3_04", "next": "ep03_s3_05", "background": "bg_rowing_locker_corridor", "ko": "그래도 말은 해 주네.", "portrait": "oliver_standing_weary"}, {"kind": "line", "speaker": "sophie", "channel": "speech", "text": "She wanted me to keep you distracted. I came because you looked awful.", "scene": 3, "id": "ep03_s3_05", "next": "ep03_s3_06", "background": "bg_rowing_locker_corridor", "ko": "클로이는 내가 네 정신을 딴 데 팔게 하길 바랐어. 난 네 얼굴이 너무 안 좋아 보여서 온 거고.", "portrait": "sophie_standing_watch"}, {"kind": "line", "speaker": "oliver", "channel": "speech", "text": "Efficient. Two jobs, one visit.", "scene": 3, "id": "ep03_s3_06", "next": "ep03_s3_07", "background": "bg_rowing_locker_corridor", "ko": "효율적이네. 한 번 와서 일 두 개.", "portrait": "oliver_standing_weary"}, {"kind": "line", "speaker": "sophie", "channel": "speech", "text": "I can leave.", "scene": 3, "id": "ep03_s3_07", "next": "ep03_s3_08", "background": "bg_rowing_locker_corridor", "ko": "갈 수도 있어.", "portrait": "sophie_standing_watch"}, {"kind": "line", "speaker": "oliver", "channel": "speech", "text": "Don’t.", "scene": 3, "id": "ep03_s3_08", "next": "ep03_s3_09", "background": "bg_rowing_locker_corridor", "ko": "가지 마.", "portrait": "oliver_standing_weary"}, {"kind": "line", "speaker": "oliver", "channel": "speech", "text": "My family likes people who make things easy. Chloe looks right in photographs. My brother says I should be grateful.", "scene": 3, "id": "ep03_s3_09", "next": "ep03_s3_10", "background": "bg_rowing_locker_corridor", "ko": "우리 가족은 일을 쉽게 만들어 주는 사람을 좋아해. 클로이는 사진에 잘 어울리고. 형은 내가 감사해야 한대.", "portrait": "oliver_standing_weary"}, {"kind": "line", "speaker": "sophie", "channel": "speech", "text": "For being convenient?", "scene": 3, "id": "ep03_s3_10", "next": "ep03_s3_11", "background": "bg_rowing_locker_corridor", "ko": "편리한 존재라서?", "portrait": "sophie_standing_watch"}, {"kind": "line", "speaker": "oliver", "channel": "speech", "text": "You make it sound worse when you say it normally.", "scene": 3, "id": "ep03_s3_11", "next": "ep03_s3_12", "background": "bg_rowing_locker_corridor", "ko": "네가 평범하게 말하니까 더 나쁘게 들린다.", "portrait": "oliver_standing_weary"}, {"kind": "line", "speaker": "oliver", "channel": "speech", "text": "Is it possible to disappoint everyone and still be a decent person?", "scene": 3, "directions": ["올리버가 문밖의 사용자에게도 말한다."], "id": "ep03_s3_12", "next": "ep03_c03", "background": "bg_rowing_locker_corridor", "ko": "모두를 실망시키고도 괜찮은 사람일 수 있을까?", "portrait": "oliver_standing_weary"}, {"kind": "choice", "choice_id": "ep03_c03", "title_ko": "자신의 선택을 할 권리", "options": [{"id": "A", "intent_ko": "다른 사람을 실망시키는 것과 해치는 것은 다르다고 말한다.", "hint_en": "Disappointing someone isn’t the same as hurting them."}, {"id": "B", "intent_ko": "본인이 원하는 것이 무엇인지 먼저 물어본다.", "hint_en": "What do you actually want?"}], "scene": 3, "id": "ep03_c03", "branch": {"A": "ep03_c03_A_1", "B": "ep03_c03_B_1"}, "rejoin": "ep03_s3_13", "next": null, "background": "bg_rowing_locker_corridor"}, {"kind": "line", "speaker": "oliver", "channel": "speech", "text": "I wish someone had told me that sooner.", "scene": 3, "in_branch": {"choice_id": "ep03_c03", "option": "A"}, "id": "ep03_c03_A_1", "next": "ep03_c03_A_2", "background": "bg_rowing_locker_corridor", "ko": "누가 그 말을 좀 더 일찍 해 줬으면 좋았을 텐데.", "portrait": "oliver_standing_accept_water"}, {"kind": "line", "speaker": "sophie", "channel": "speech", "text": "You can hear it now.", "scene": 3, "in_branch": {"choice_id": "ep03_c03", "option": "A"}, "id": "ep03_c03_A_2", "next": "ep03_s3_13", "background": "bg_rowing_locker_corridor", "ko": "지금이라도 들으면 되지.", "portrait": "sophie_standing_watch"}, {"kind": "line", "speaker": "oliver", "channel": "speech", "text": "One decision that doesn’t arrive with my family’s signature.", "scene": 3, "in_branch": {"choice_id": "ep03_c03", "option": "B"}, "id": "ep03_c03_B_1", "next": "ep03_c03_B_2", "background": "bg_rowing_locker_corridor", "ko": "우리 가족 서명이 붙어 오지 않는 결정 하나.", "portrait": "oliver_standing_weary"}, {"kind": "line", "speaker": "sophie", "channel": "speech", "text": "Start smaller. Do you want me here?", "scene": 3, "in_branch": {"choice_id": "ep03_c03", "option": "B"}, "id": "ep03_c03_B_2", "next": "ep03_s3_13", "background": "bg_rowing_locker_corridor", "ko": "작은 것부터 해 봐. 내가 여기 있었으면 좋겠어?", "portrait": "sophie_standing_watch"}, {"kind": "line", "speaker": "oliver", "channel": "speech", "text": "Yes.", "scene": 3, "id": "ep03_s3_13", "next": "ep03_s3_14", "background": "bg_rowing_locker_corridor", "ko": "응.", "portrait": "oliver_standing_weary"}, {"kind": "line", "speaker": "sophie", "channel": "speech", "text": "I want to kiss you. That’s not Chloe’s idea.", "scene": 3, "id": "ep03_s3_14", "next": "ep03_s3_15", "background": "bg_rowing_locker_corridor", "ko": "너한테 키스하고 싶어. 클로이 생각이 아니라 내 생각이야.", "portrait": "sophie_standing_offer_water"}, {"kind": "line", "speaker": "oliver", "channel": "speech", "text": "I know.", "scene": 3, "id": "ep03_s3_15", "next": "ep03_s4_01", "background": "bg_rowing_locker_corridor", "ko": "알아.", "portrait": "oliver_standing_weary"}, {"kind": "line", "speaker": "narration", "channel": "narration", "text": "Later, Sophie catches up with you. Her phone keeps buzzing.", "scene": 4, "directions": ["서로 잠깐 확인한 뒤 입맞춤. 사용자는 시선을 돌려 자리를 비켜준다."], "id": "ep03_s4_01", "next": "ep03_s4_02", "background": "bg_dorm_corridor_evening", "ko": "잠시 후, 소피가 당신을 따라온다. 소피의 휴대폰이 계속 울린다."}, {"kind": "line", "speaker": "sophie", "channel": "speech", "text": "I told myself I was helping. Then I kissed someone who’s still engaged.", "scene": 4, "id": "ep03_s4_02", "next": "ep03_c04", "background": "bg_dorm_corridor_evening", "ko": "돕는 거라고 스스로 말했어. 그러고는 아직 약혼한 사람한테 키스했지.", "portrait": "sophie_standing_watch"}, {"kind": "choice", "choice_id": "ep03_c04", "title_ko": "친구에게 솔직하게 말하기", "options": [{"id": "A", "intent_ko": "감정이 진짜여도 약혼 문제는 먼저 해결해야 한다고 말한다.", "hint_en": "Your feelings can be real, but he needs to end the engagement first."}, {"id": "B", "intent_ko": "올리버에게 관계를 분명하게 해 달라고 요청하라고 한다.", "hint_en": "Ask him to be clear about where you stand."}], "scene": 4, "id": "ep03_c04", "branch": {"A": "ep03_c04_A_1", "B": "ep03_c04_B_1"}, "rejoin": "ep03_s4_03", "next": null, "background": "bg_dorm_corridor_evening"}, {"kind": "line", "speaker": "sophie", "channel": "speech", "text": "I know. I don’t want to become another excuse.", "scene": 4, "in_branch": {"choice_id": "ep03_c04", "option": "A"}, "id": "ep03_c04_A_1", "next": "ep03_c04_A_2", "background": "bg_dorm_corridor_evening", "ko": "알아. 또 하나의 핑계가 되고 싶진 않아.", "portrait": "sophie_standing_watch"}, {"kind": "line", "speaker": "sophie", "channel": "speech", "text": "I’ll tell him.", "scene": 4, "in_branch": {"choice_id": "ep03_c04", "option": "A"}, "id": "ep03_c04_A_2", "next": "ep03_s4_03", "background": "bg_dorm_corridor_evening", "ko": "올리버한테 말할게.", "portrait": "sophie_standing_watch"}, {"kind": "line", "speaker": "sophie", "channel": "speech", "text": "No secret arrangement. No waiting until it’s convenient.", "scene": 4, "in_branch": {"choice_id": "ep03_c04", "option": "B"}, "id": "ep03_c04_B_1", "next": "ep03_c04_B_2", "background": "bg_dorm_corridor_evening", "ko": "몰래 하는 약속도, 편할 때까지 기다리는 것도 없이.", "portrait": "sophie_standing_watch"}, {"kind": "line", "speaker": "sophie", "channel": "speech", "text": "That sounds terrifying. And fair.", "scene": 4, "in_branch": {"choice_id": "ep03_c04", "option": "B"}, "id": "ep03_c04_B_2", "next": "ep03_s4_03", "background": "bg_dorm_corridor_evening", "ko": "무섭게 들린다. 그리고 공평하네.", "portrait": "sophie_standing_watch"}, {"kind": "line", "speaker": "chloe", "channel": "speech", "text": "Luna’s still here. Change of plan.", "scene": 4, "audience": true, "directions": ["관객 전용: 소피가 클로이의 전화를 받는다."], "id": "ep03_s4_03", "next": "ep03_s4_04", "background": "bg_dorm_corridor_evening", "ko": "루나가 아직 안 떠났어. 계획 바꿔.", "portrait": "chloe_standing_guarded"}, {"kind": "line", "speaker": "sophie", "channel": "speech", "text": "What plan?", "scene": 4, "audience": true, "id": "ep03_s4_04", "next": "ep03_s4_05", "background": "bg_dorm_corridor_evening", "ko": "무슨 계획?"}, {"kind": "line", "speaker": "chloe", "channel": "speech", "text": "She leaves the faculty office with a stolen exam. Security finds it. You make sure she’s there.", "scene": 4, "audience": true, "id": "ep03_s4_05", "next": "ep03_s4_06", "background": "bg_dorm_corridor_evening", "ko": "루나가 훔친 시험지를 들고 교수 연구실에서 나오는 거야. 보안팀이 그걸 찾아내고. 넌 루나가 거기 있게만 만들어.", "portrait": "chloe_standing_guarded"}, {"kind": "line", "speaker": "sophie", "channel": "speech", "text": "You’re asking me to ruin her life.", "scene": 4, "audience": true, "id": "ep03_s4_06", "next": "ep03_s4_07", "background": "bg_dorm_corridor_evening", "ko": "나더러 루나 인생을 망치라는 거잖아."}, {"kind": "line", "speaker": "chloe", "channel": "speech", "text": "I’m asking whether you’d prefer I ruin yours.", "scene": 4, "audience": true, "id": "ep03_s4_07", "next": "ep03_s4_08", "background": "bg_dorm_corridor_evening", "ko": "아니면 내가 네 인생을 망치는 게 낫겠냐고 묻는 거야.", "portrait": "chloe_standing_guarded"}, {"kind": "line", "speaker": "end_card", "channel": "end_card", "text": "One honest answer. One impossible order.", "scene": 4, "audience": true, "id": "ep03_s4_08", "next": null, "background": "bg_dorm_corridor_evening", "ko": "하나의 솔직한 대답. 하나의 불가능한 명령."}]}, "red_ivy_s1_ep04": {"story_id": "red_ivy_s1", "episode_id": "red_ivy_s1_ep04", "number": 4, "title": "The Wrong Red Dress", "access": "free", "start": "ep04_s1_01", "scenes": [{"index": 1, "place_ko": "가면무도회 / 저녁", "background": "bg_masquerade_hall_evening"}, {"index": 2, "place_ko": "교수 연구실 복도", "background": "bg_faculty_corridor_night"}, {"index": 3, "place_ko": "복도 끝", "background": "bg_faculty_corridor_night"}, {"index": 4, "place_ko": "무도회 입구", "background": "bg_masquerade_entrance_night"}], "nodes": [{"kind": "line", "speaker": "narration", "channel": "narration", "text": "Two weeks later, Crimson hosts its masquerade. You’re helping with check-in. Chloe has lent Sophie a red dress. Luna has received an invitation to meet a professor about Elena.", "scene": 1, "id": "ep04_s1_01", "next": "ep04_s1_02", "background": "bg_masquerade_hall_evening", "ko": "2주 뒤, 크림슨 클럽의 가면무도회. 당신은 입장 확인을 돕고 있다. 클로이는 소피에게 붉은 드레스를 빌려줬다. 루나는 엘레나에 대해 교수를 만나자는 초대를 받았다."}, {"kind": "line", "speaker": "julian", "channel": "speech", "text": "Masks stay on until ten. Regrets are available all evening.", "scene": 1, "id": "ep04_s1_02", "next": "ep04_s1_03", "background": "bg_masquerade_hall_evening", "ko": "가면은 10시까지 쓰고 계세요. 후회는 밤새 언제든 가능합니다.", "portrait": "julian_standing_host"}, {"kind": "line", "speaker": "sophie", "channel": "speech", "text": "You sound rehearsed.", "scene": 1, "id": "ep04_s1_03", "next": "ep04_s1_04", "background": "bg_masquerade_hall_evening", "ko": "연습한 티 나.", "portrait": "sophie_standing_dry_smile"}, {"kind": "line", "speaker": "julian", "channel": "speech", "text": "It’s a party. Nobody wants the first draft.", "scene": 1, "id": "ep04_s1_04", "next": "ep04_s1_05", "background": "bg_masquerade_hall_evening", "ko": "파티잖아. 초안을 듣고 싶은 사람은 없어.", "portrait": "julian_standing_joke"}, {"kind": "line", "speaker": "chloe", "channel": "speech", "text": "Professor Bell’s office. Nine fifteen. Walk Luna there.", "scene": 1, "directions": ["클로이가 소피의 리본을 매만진다."], "id": "ep04_s1_05", "next": "ep04_s1_06", "background": "bg_masquerade_hall_evening", "ko": "벨 교수 연구실. 9시 15분. 루나를 거기까지 데려가.", "portrait": "chloe_standing_host"}, {"kind": "line", "speaker": "sophie", "channel": "speech", "text": "You said we were done after tonight.", "scene": 1, "id": "ep04_s1_06", "next": "ep04_s1_07", "background": "bg_masquerade_hall_evening", "ko": "오늘 밤이 마지막이라고 했잖아.", "portrait": "sophie_standing_watch"}, {"kind": "line", "speaker": "chloe", "channel": "speech", "text": "Then finish.", "scene": 1, "id": "ep04_s1_07", "next": "ep04_s1_08", "background": "bg_masquerade_hall_evening", "ko": "그럼 끝내.", "portrait": "chloe_standing_guarded"}, {"kind": "line", "speaker": "julian", "channel": "speech", "text": "You can stop pretending with me.", "scene": 1, "directions": ["클로이가 떠난다. 줄리언은 붉은 드레스의 소피를 클로이로 착각해 다가온다."], "id": "ep04_s1_08", "next": "ep04_s1_09", "background": "bg_masquerade_hall_evening", "ko": "나한텐 그만 연기해도 돼.", "portrait": "julian_standing_jealous"}, {"kind": "line", "speaker": "sophie", "channel": "speech", "text": "Pretending what?", "scene": 1, "id": "ep04_s1_09", "next": "ep04_s1_10", "background": "bg_masquerade_hall_evening", "ko": "뭘 연기해?", "portrait": "sophie_standing_watch"}, {"kind": "line", "speaker": "julian", "channel": "speech", "text": "That Oliver makes you happy. That Ethan will ever stay.", "scene": 1, "id": "ep04_s1_10", "next": "ep04_s1_11", "background": "bg_masquerade_hall_evening", "ko": "올리버랑 있어서 행복한 척. 이든이 언젠가 곁에 남을 거라는 척.", "portrait": "julian_standing_jealous"}, {"kind": "line", "speaker": "julian", "channel": "speech", "text": "I’ve been right here, Chloe. This whole time.", "scene": 1, "id": "ep04_s1_11", "next": "ep04_s1_12", "background": "bg_masquerade_hall_evening", "ko": "난 계속 여기 있었어, 클로이. 처음부터 쭉.", "portrait": "julian_standing_jealous"}, {"kind": "line", "speaker": "sophie", "channel": "speech", "text": "Wrong audience.", "scene": 1, "directions": ["소피가 가면을 벗는다."], "id": "ep04_s1_12", "next": "ep04_s1_13", "background": "bg_masquerade_hall_evening", "ko": "사람 잘못 봤어.", "portrait": "sophie_standing_dry_smile"}, {"kind": "line", "speaker": "julian", "channel": "speech", "text": "Sophie. God. I’m sorry.", "scene": 1, "id": "ep04_s1_13", "next": "ep04_s1_14", "background": "bg_masquerade_hall_evening", "ko": "소피. 세상에. 미안해.", "portrait": "julian_standing_host"}, {"kind": "line", "speaker": "sophie", "channel": "speech", "text": "For saying it, or for saying it to me?", "scene": 1, "id": "ep04_s1_14", "next": "ep04_c01", "background": "bg_masquerade_hall_evening", "ko": "그 말을 한 게 미안해, 아니면 나한테 한 게 미안해?", "portrait": "sophie_standing_watch"}, {"kind": "choice", "choice_id": "ep04_c01", "title_ko": "어색한 고백 뒤 개입", "options": [{"id": "A", "intent_ko": "줄리언에게 소피에게 제대로 사과하라고 말한다.", "hint_en": "Julian, you owe Sophie a real apology."}, {"id": "B", "intent_ko": "소피에게 잠깐 바람을 쐬러 가겠냐고 묻는다.", "hint_en": "Sophie, do you want to get some air?"}], "scene": 1, "directions": ["사용자가 가까이 온다."], "id": "ep04_c01", "branch": {"A": "ep04_c01_A_1", "B": "ep04_c01_B_1"}, "rejoin": "ep04_s1_15", "next": null, "background": "bg_masquerade_hall_evening"}, {"kind": "line", "speaker": "julian", "channel": "speech", "text": "You’re right. Sophie, I treated you like a costume. You didn’t deserve that.", "scene": 1, "in_branch": {"choice_id": "ep04_c01", "option": "A"}, "id": "ep04_c01_A_1", "next": "ep04_c01_A_2", "background": "bg_masquerade_hall_evening", "ko": "맞아. 소피, 널 의상 취급했어. 넌 그런 대접 받을 사람이 아니야.", "portrait": "julian_standing_host"}, {"kind": "line", "speaker": "sophie", "channel": "speech", "text": "No. I didn’t.", "scene": 1, "in_branch": {"choice_id": "ep04_c01", "option": "A"}, "id": "ep04_c01_A_2", "next": "ep04_s1_15", "background": "bg_masquerade_hall_evening", "ko": "그래. 아니었지.", "portrait": "sophie_standing_watch"}, {"kind": "line", "speaker": "sophie", "channel": "speech", "text": "Yes. Before someone else mistakes me for a better investment.", "scene": 1, "in_branch": {"choice_id": "ep04_c01", "option": "B"}, "id": "ep04_c01_B_1", "next": "ep04_c01_B_2", "background": "bg_masquerade_hall_evening", "ko": "응. 누가 또 날 더 나은 투자처로 착각하기 전에.", "portrait": "sophie_standing_watch"}, {"kind": "line", "speaker": "julian", "channel": "speech", "text": "That’s not what I meant. But I heard how it sounded.", "scene": 1, "in_branch": {"choice_id": "ep04_c01", "option": "B"}, "id": "ep04_c01_B_2", "next": "ep04_s1_15", "background": "bg_masquerade_hall_evening", "ko": "그런 뜻은 아니었어. 그래도 어떻게 들렸는지는 알아.", "portrait": "julian_standing_host"}, {"kind": "line", "speaker": "sophie", "channel": "speech", "text": "I have to find Luna. Something’s wrong.", "scene": 1, "id": "ep04_s1_15", "next": "ep04_s2_01", "background": "bg_masquerade_hall_evening", "ko": "루나를 찾아야 해. 뭔가 잘못됐어.", "portrait": "sophie_standing_watch"}, {"kind": "line", "speaker": "narration", "channel": "narration", "text": "Luna is waiting outside Professor Bell’s office. You follow Sophie into the quiet hallway.", "scene": 2, "id": "ep04_s2_01", "next": "ep04_s2_02", "background": "bg_faculty_corridor_night", "ko": "루나가 벨 교수 연구실 앞에서 기다리고 있다. 당신은 소피를 따라 조용한 복도로 들어선다."}, {"kind": "line", "speaker": "luna", "channel": "speech", "text": "His office is dark. Are you sure he’s expecting me?", "scene": 2, "id": "ep04_s2_02", "next": "ep04_s2_03", "background": "bg_faculty_corridor_night", "ko": "연구실 불이 꺼져 있어. 교수님이 날 기다리는 거 맞아?", "portrait": "luna_standing_observe"}, {"kind": "line", "speaker": "sophie", "channel": "speech", "text": "Don’t go in.", "scene": 2, "id": "ep04_s2_03", "next": "ep04_s2_04", "background": "bg_faculty_corridor_night", "ko": "들어가지 마.", "portrait": "sophie_standing_watch"}, {"kind": "line", "speaker": "luna", "channel": "speech", "text": "You brought me here.", "scene": 2, "id": "ep04_s2_04", "next": "ep04_s2_05", "background": "bg_faculty_corridor_night", "ko": "네가 날 여기 데려왔잖아.", "portrait": "luna_standing_observe"}, {"kind": "line", "speaker": "sophie", "channel": "speech", "text": "I know. I’m trying to undo it.", "scene": 2, "id": "ep04_s2_05", "next": "ep04_s2_06", "background": "bg_faculty_corridor_night", "ko": "알아. 그걸 되돌리려는 거야.", "portrait": "sophie_standing_watch"}, {"kind": "line", "speaker": "dean", "channel": "speech", "text": "Luna? We received a report about missing examination materials.", "scene": 2, "directions": ["보안 직원과 학장이 다가온다."], "id": "ep04_s2_06", "next": "ep04_s2_07", "background": "bg_faculty_corridor_night", "ko": "루나 학생? 시험 자료가 없어졌다는 신고가 들어왔어요."}, {"kind": "line", "speaker": "luna", "channel": "speech", "text": "From whom?", "scene": 2, "id": "ep04_s2_07", "next": "ep04_s2_08", "background": "bg_faculty_corridor_night", "ko": "누가요?", "portrait": "luna_standing_observe"}, {"kind": "line", "speaker": "dean", "channel": "speech", "text": "We need to ask you some questions.", "scene": 2, "id": "ep04_s2_08", "next": "ep04_s2_09", "background": "bg_faculty_corridor_night", "ko": "몇 가지 물어볼 게 있어요."}, {"kind": "line", "speaker": "sophie", "channel": "speech", "text": "She was invited here. By me.", "scene": 2, "id": "ep04_s2_09", "next": "ep04_s2_10", "background": "bg_faculty_corridor_night", "ko": "루나는 초대받아서 온 거예요. 제가 불렀어요.", "portrait": "sophie_standing_watch"}, {"kind": "line", "speaker": "dean", "channel": "speech", "text": "We’ll speak to you separately.", "scene": 2, "id": "ep04_s2_10", "next": "ep04_s2_11", "background": "bg_faculty_corridor_night", "ko": "학생과는 따로 이야기하죠."}, {"kind": "line", "speaker": "luna", "channel": "speech", "text": "This isn’t mine.", "scene": 2, "directions": ["루나는 가방을 열어 보이다 낯선 봉투를 발견한다."], "id": "ep04_s2_11", "next": "ep04_s2_12", "background": "bg_faculty_corridor_night", "ko": "이건 제 게 아니에요.", "portrait": "luna_standing_observe"}, {"kind": "line", "speaker": "security", "channel": "speech", "text": "Please leave it where it is.", "scene": 2, "id": "ep04_s2_12", "next": "ep04_c02", "background": "bg_faculty_corridor_night", "ko": "그대로 두세요."}, {"kind": "choice", "choice_id": "ep04_c02", "title_ko": "성급한 결론 막기", "options": [{"id": "A", "intent_ko": "가방에서 나왔다는 것만으로 가져간 사람을 알 수는 없다고 말한다.", "hint_en": "Finding it in her bag doesn’t tell us who put it there."}, {"id": "B", "intent_ko": "현장에서 본 내용을 별도로 진술하겠다고 한다.", "hint_en": "I’d like to give a separate statement about what I saw."}], "scene": 2, "id": "ep04_c02", "branch": {"A": "ep04_c02_A_1", "B": "ep04_c02_B_1"}, "rejoin": "ep04_s2_13", "next": null, "background": "bg_faculty_corridor_night"}, {"kind": "line", "speaker": "dean", "channel": "speech", "text": "No finding has been made. This will be reviewed.", "scene": 2, "in_branch": {"choice_id": "ep04_c02", "option": "A"}, "id": "ep04_c02_A_1", "next": "ep04_c02_A_2", "background": "bg_faculty_corridor_night", "ko": "아직 결론 난 건 없어요. 검토할 겁니다."}, {"kind": "line", "speaker": "luna", "channel": "speech", "text": "Then please speak to me like that’s true.", "scene": 2, "in_branch": {"choice_id": "ep04_c02", "option": "A"}, "id": "ep04_c02_A_2", "next": "ep04_s2_13", "background": "bg_faculty_corridor_night", "ko": "그럼 정말 그런 것처럼 말해 주세요.", "portrait": "luna_standing_observe"}, {"kind": "line", "speaker": "security", "channel": "speech", "text": "Give us your name. We’ll take your statement separately.", "scene": 2, "in_branch": {"choice_id": "ep04_c02", "option": "B"}, "id": "ep04_c02_B_1", "next": "ep04_c02_B_2", "background": "bg_faculty_corridor_night", "ko": "이름을 알려 주세요. 진술은 따로 받겠습니다."}, {"kind": "line", "speaker": "sophie", "channel": "speech", "text": "Take mine, too. All of it.", "scene": 2, "in_branch": {"choice_id": "ep04_c02", "option": "B"}, "id": "ep04_c02_B_2", "next": "ep04_s2_13", "background": "bg_faculty_corridor_night", "ko": "제 것도 받아 주세요. 전부 다.", "portrait": "sophie_standing_watch"}, {"kind": "line", "speaker": "chloe", "channel": "speech", "text": "Luna? What happened?", "scene": 2, "id": "ep04_s2_13", "next": "ep04_s2_14", "background": "bg_faculty_corridor_night", "ko": "루나? 무슨 일이야?", "portrait": "chloe_standing_guarded"}, {"kind": "line", "speaker": "luna", "channel": "speech", "text": "You tell me.", "scene": 2, "id": "ep04_s2_14", "next": "ep04_s2_15", "background": "bg_faculty_corridor_night", "ko": "네가 말해 봐.", "portrait": "luna_standing_observe"}, {"kind": "line", "speaker": "chloe", "channel": "speech", "text": "Careful. Accusations need evidence.", "scene": 2, "id": "ep04_s2_15", "next": "ep04_s3_01", "background": "bg_faculty_corridor_night", "ko": "조심해. 누굴 탓하려면 증거가 필요하거든.", "portrait": "chloe_standing_guarded"}, {"kind": "line", "speaker": "oliver", "channel": "speech", "text": "What time were the papers taken?", "scene": 3, "directions": ["올리버가 소란을 듣고 온다."], "id": "ep04_s3_01", "next": "ep04_s3_02", "background": "bg_faculty_corridor_night", "ko": "시험지가 없어진 게 몇 시예요?", "portrait": "oliver_standing_weary"}, {"kind": "line", "speaker": "dean", "channel": "speech", "text": "Between eight forty and nine, according to the initial report.", "scene": 3, "id": "ep04_s3_02", "next": "ep04_s3_03", "background": "bg_faculty_corridor_night", "ko": "첫 신고에 따르면 8시 40분에서 9시 사이예요."}, {"kind": "line", "speaker": "oliver", "channel": "speech", "text": "Luna was with me. Outside, by the courtyard.", "scene": 3, "id": "ep04_s3_03", "next": "ep04_s3_04", "background": "bg_faculty_corridor_night", "ko": "루나는 저랑 있었어요. 밖에, 안뜰 옆에서요.", "portrait": "oliver_standing_weary"}, {"kind": "line", "speaker": "chloe", "channel": "speech", "text": "Oliver. Think carefully.", "scene": 3, "id": "ep04_s3_04", "next": "ep04_s3_05", "background": "bg_faculty_corridor_night", "ko": "올리버. 잘 생각해.", "portrait": "chloe_standing_guarded"}, {"kind": "line", "speaker": "oliver", "channel": "speech", "text": "I am.", "scene": 3, "id": "ep04_s3_05", "next": "ep04_s3_06", "background": "bg_faculty_corridor_night", "ko": "하고 있어.", "portrait": "oliver_standing_weary"}, {"kind": "line", "speaker": "luna", "channel": "speech", "text": "We talked about Elena.", "scene": 3, "id": "ep04_s3_06", "next": "ep04_s3_07", "background": "bg_faculty_corridor_night", "ko": "엘레나 얘기를 했어요.", "portrait": "luna_standing_softened"}, {"kind": "line", "speaker": "oliver", "channel": "speech", "text": "And I should have done that sooner.", "scene": 3, "id": "ep04_s3_07", "next": "ep04_s3_08", "background": "bg_faculty_corridor_night", "ko": "더 일찍 했어야 했던 얘기죠.", "portrait": "oliver_standing_weary"}, {"kind": "line", "speaker": "dean", "channel": "speech", "text": "We’ll check the timing. Both of you will need to give statements.", "scene": 3, "id": "ep04_s3_08", "next": "ep04_s3_09", "background": "bg_faculty_corridor_night", "ko": "시간을 확인하겠습니다. 두 사람 다 진술해야 해요."}, {"kind": "line", "speaker": "luna", "channel": "speech", "text": "I thought they were going to decide before I opened my mouth.", "scene": 3, "directions": ["학장이 이동한다. 루나는 사용자를 향한다."], "id": "ep04_s3_09", "next": "ep04_c03", "background": "bg_faculty_corridor_night", "ko": "내가 입을 열기도 전에 결론 내릴 줄 알았어요.", "portrait": "luna_standing_softened"}, {"kind": "choice", "choice_id": "ep04_c03", "title_ko": "다음 행동 정하기", "options": [{"id": "A", "intent_ko": "기억이 흐려지기 전에 시간 순서를 적자고 한다.", "hint_en": "Let’s write down the timeline while it’s fresh."}, {"id": "B", "intent_ko": "조사 절차를 함께 확인해 줄 사람을 찾자고 한다.", "hint_en": "Let’s find someone who can help you understand the process."}], "scene": 3, "id": "ep04_c03", "branch": {"A": "ep04_c03_A_1", "B": "ep04_c03_B_1"}, "rejoin": "ep04_s3_10", "next": null, "background": "bg_faculty_corridor_night"}, {"kind": "line", "speaker": "luna", "channel": "speech", "text": "Eight forty-five, courtyard. Just before nine, Sophie’s message.", "scene": 3, "in_branch": {"choice_id": "ep04_c03", "option": "A"}, "id": "ep04_c03_A_1", "next": "ep04_c03_A_2", "background": "bg_faculty_corridor_night", "ko": "8시 45분, 안뜰. 9시 직전에 소피의 메시지.", "portrait": "luna_standing_softened"}, {"kind": "line", "speaker": "oliver", "channel": "speech", "text": "I still have the photo I took of the clock outside. It helps place us there.", "scene": 3, "in_branch": {"choice_id": "ep04_c03", "option": "A"}, "id": "ep04_c03_A_2", "next": "ep04_s3_10", "background": "bg_faculty_corridor_night", "ko": "밖에 있는 시계를 찍은 사진이 아직 있어. 우리가 거기 있었다는 걸 보여 줄 수 있어.", "portrait": "oliver_standing_accept_water"}, {"kind": "line", "speaker": "luna", "channel": "speech", "text": "The student adviser. I have her email.", "scene": 3, "in_branch": {"choice_id": "ep04_c03", "option": "B"}, "id": "ep04_c03_B_1", "next": "ep04_c03_B_2", "background": "bg_faculty_corridor_night", "ko": "학생 상담 선생님이요. 이메일 주소가 있어요.", "portrait": "luna_standing_softened"}, {"kind": "line", "speaker": "oliver", "channel": "speech", "text": "I’ll wait while you call. You shouldn’t have to explain this alone.", "scene": 3, "in_branch": {"choice_id": "ep04_c03", "option": "B"}, "id": "ep04_c03_B_2", "next": "ep04_s3_10", "background": "bg_faculty_corridor_night", "ko": "전화하는 동안 기다릴게. 혼자서 이걸 설명할 필요는 없어.", "portrait": "oliver_standing_accept_water"}, {"kind": "line", "speaker": "luna", "channel": "speech", "text": "I’m not asking anyone to lie for me.", "scene": 3, "id": "ep04_s3_10", "next": "ep04_s3_11", "background": "bg_faculty_corridor_night", "ko": "나 대신 거짓말해 달라는 게 아니에요.", "portrait": "luna_standing_softened"}, {"kind": "line", "speaker": "oliver", "channel": "speech", "text": "You don’t have to. This time I’m telling the truth.", "scene": 3, "id": "ep04_s3_11", "next": "ep04_s4_01", "background": "bg_faculty_corridor_night", "ko": "그럴 필요 없어. 이번엔 내가 진실을 말하는 거니까.", "portrait": "oliver_standing_accept_water"}, {"kind": "line", "speaker": "sophie", "channel": "speech", "text": "I knew she was planning something. I told myself I could stop it later.", "scene": 4, "directions": ["사용자와 소피가 남는다."], "id": "ep04_s4_01", "next": "ep04_s4_02", "background": "bg_masquerade_entrance_night", "ko": "클로이가 뭔가 꾸미는 줄 알았어. 나중에 막을 수 있다고 스스로 말했지.", "portrait": "sophie_standing_watch"}, {"kind": "line", "speaker": "sophie", "channel": "speech", "text": "Later is a wonderful word when you’re a coward.", "scene": 4, "id": "ep04_s4_02", "next": "ep04_c04", "background": "bg_masquerade_entrance_night", "ko": "겁쟁이한테 ‘나중에’는 참 좋은 말이야.", "portrait": "sophie_standing_watch"}, {"kind": "choice", "choice_id": "ep04_c04", "title_ko": "책임 있는 도움 요청", "options": [{"id": "A", "intent_ko": "자책보다 알고 있는 사실을 말하는 게 먼저라고 한다.", "hint_en": "Start with what you know. Blaming yourself can wait."}, {"id": "B", "intent_ko": "누구의 지시였는지 분명히 말해 달라고 한다.", "hint_en": "Tell me clearly who asked you to do this."}], "scene": 4, "id": "ep04_c04", "branch": {"A": "ep04_c04_A_1", "B": "ep04_c04_B_1"}, "rejoin": "ep04_s4_03", "next": null, "background": "bg_masquerade_entrance_night"}, {"kind": "line", "speaker": "sophie", "channel": "speech", "text": "Right. I’ll write it down. Even the parts that make me look guilty.", "scene": 4, "in_branch": {"choice_id": "ep04_c04", "option": "A"}, "id": "ep04_c04_A_1", "next": "ep04_c04_A_2", "background": "bg_masquerade_entrance_night", "ko": "맞아. 적어 둘게. 내가 잘못한 것처럼 보이는 부분까지.", "portrait": "sophie_standing_watch"}, {"kind": "line", "speaker": "sophie", "channel": "speech", "text": "Especially those.", "scene": 4, "in_branch": {"choice_id": "ep04_c04", "option": "A"}, "id": "ep04_c04_A_2", "next": "ep04_s4_03", "background": "bg_masquerade_entrance_night", "ko": "특히 그 부분은.", "portrait": "sophie_standing_watch"}, {"kind": "line", "speaker": "sophie", "channel": "speech", "text": "Chloe. She threatened me, but I still agreed to bring Luna here.", "scene": 4, "in_branch": {"choice_id": "ep04_c04", "option": "B"}, "id": "ep04_c04_B_1", "next": "ep04_c04_B_2", "background": "bg_masquerade_entrance_night", "ko": "클로이야. 협박받았지만, 루나를 여기 데려오겠다고 한 건 나야.", "portrait": "sophie_standing_watch"}, {"kind": "line", "speaker": "sophie", "channel": "speech", "text": "I won’t pretend I had no choice.", "scene": 4, "in_branch": {"choice_id": "ep04_c04", "option": "B"}, "id": "ep04_c04_B_2", "next": "ep04_s4_03", "background": "bg_masquerade_entrance_night", "ko": "선택지가 없었던 척은 안 할게.", "portrait": "sophie_standing_watch"}, {"kind": "line", "speaker": "chloe", "channel": "speech", "text": "You chose her over me.", "scene": 4, "audience": true, "directions": ["관객 전용: 클로이와 올리버."], "id": "ep04_s4_03", "next": "ep04_s4_04", "background": "bg_masquerade_entrance_night", "ko": "날 두고 걔를 택했네.", "portrait": "chloe_standing_vulnerable"}, {"kind": "line", "speaker": "oliver", "channel": "speech", "text": "I chose something that actually happened.", "scene": 4, "audience": true, "id": "ep04_s4_04", "next": "ep04_s4_05", "background": "bg_masquerade_entrance_night", "ko": "실제로 있었던 일을 택한 거야.", "portrait": "oliver_standing_weary"}, {"kind": "line", "speaker": "chloe", "channel": "speech", "text": "Since when does that matter to you?", "scene": 4, "audience": true, "id": "ep04_s4_05", "next": "ep04_s4_06", "background": "bg_masquerade_entrance_night", "ko": "언제부터 그게 너한테 중요했는데?", "portrait": "chloe_standing_guarded"}, {"kind": "line", "speaker": "end_card", "channel": "end_card", "text": "One true alibi. One old lie.", "scene": 4, "audience": true, "directions": ["올리버가 굳는다."], "id": "ep04_s4_06", "next": null, "background": "bg_masquerade_entrance_night", "ko": "하나의 진짜 알리바이. 하나의 오래된 거짓말."}]}}};
// Appended after sophie-chat-core.mjs (with PROMPTS inlined) to form the Vercel function api/ai.mjs (POST /api/ai).
// Env vars (Vercel → Settings → Environment Variables, Production): GEMINI_API_KEY, GEMINI_MODEL, SOPHIE_INVITE_CODE,
// optional SOPHIE_DAILY_LIMIT. Logs (Vercel → Logs) start with [ai] and never contain the key, invite code or chat text.
let handle;
export default async function handler(req, res) {
  res.setHeader('cache-control', 'no-store');
  if (req.method !== 'POST') { res.status(405).json({ ok: false, error: 'method' }); return; }
  handle ??= createSophieHandler({ env: { ...process.env, hosted: true }, prompts: PROMPTS, redIvy: RED_IVY, log: (...a) => console.log('[ai]', ...a) });
  let body = req.body; if (typeof body === 'string') { try { body = JSON.parse(body); } catch { body = null; } }
  const out = await handle({ body, headers: req.headers });
  res.status(out.status).json(out.json);
}
